with quiz_seed(slug, original_hash, questions) as (values
  ('never-outshine-the-master', 'b2e28c18943090b557baa646e7b5af97',
    '[{"id":"identify-the-risk","questionEn":"A project lead introduces your prototype to sponsors. Which risk does this lesson most directly address?","questionBn":"একজন প্রকল্পনেতা পৃষ্ঠপোষকদের কাছে আপনার প্রোটোটাইপ তুলে ধরছেন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["An absence or departure can interrupt an essential service when knowledge is concentrated.","Personal relationships can bias judgments about who will perform well.","Visible contributions may be mistaken for a challenge to the lead''s status.","Announcing tentative terms can reduce room to negotiate or create premature expectations."],"optionsBn":["জ্ঞান একজনের হাতে কেন্দ্রীভূত থাকলে তাঁর অনুপস্থিতি বা প্রস্থানে জরুরি সেবা বন্ধ হতে পারে।","ব্যক্তিগত সম্পর্ক কে ভালো কাজ করবেন সেই বিচারে পক্ষপাত আনতে পারে।","প্রকাশ্য অবদানকে নেতার মর্যাদার প্রতি চ্যালেঞ্জ বলে ভুল বোঝা হতে পারে।","অস্থায়ী শর্ত ঘোষণা করলে আলোচনার সুযোগ কমে বা অকালে প্রত্যাশা তৈরি হয়।"],"correctOption":2,"explanationEn":"Visible contributions may be mistaken for a challenge to the lead''s status.","explanationBn":"প্রকাশ্য অবদানকে নেতার মর্যাদার প্রতি চ্যালেঞ্জ বলে ভুল বোঝা হতে পারে।"},{"id":"apply-the-boundary","questionEn":"A project lead introduces your prototype to sponsors. Which safeguard best prevents misusing this principle here?","questionBn":"একজন প্রকল্পনেতা পৃষ্ঠপোষকদের কাছে আপনার প্রোটোটাইপ তুলে ধরছেন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Distinguish legitimate confidentiality from omissions that affect informed consent. Name when and to whom more can be disclosed.","If quality or safety is at risk, raise the facts through the responsible channel promptly. Giving credit should never obscure who did the work.","Brevity works when the listener can act on what you said. Include dependencies or uncertainty if leaving them out would cause a bad decision.","A quick correction builds trust only when it is as visible as the original claim. Record the process that prevented the verification step."],"optionsBn":["বৈধ গোপনীয়তা ও অবহিত সম্মতিতে প্রভাব ফেলা তথ্য গোপনের পার্থক্য বুঝুন। কখন ও কাকে বিস্তারিত বলা যাবে তা জানান।","মান বা নিরাপত্তা ঝুঁকিতে থাকলে দায়িত্বপ্রাপ্ত পথে দ্রুত তথ্য জানান। কৃতিত্ব ভাগ করতে গিয়ে কে কাজ করেছেন তা আড়াল করা উচিত নয়।","শ্রোতা আপনার কথা থেকে কাজ করতে পারলেই সংক্ষিপ্ততা কার্যকর। বাদ দিলে ভুল সিদ্ধান্ত হতে পারে এমন নির্ভরতা বা অনিশ্চয়তা জানান।","দ্রুত সংশোধনী তখনই আস্থা গড়ে যখন তা মূল দাবির মতোই দৃশ্যমান হয়। কোন প্রক্রিয়ায় যাচাই বাদ পড়েছিল তা নথিভুক্ত করুন।"],"correctOption":1,"explanationEn":"If quality or safety is at risk, raise the facts through the responsible channel promptly. Giving credit should never obscure who did the work.","explanationBn":"মান বা নিরাপত্তা ঝুঁকিতে থাকলে দায়িত্বপ্রাপ্ত পথে দ্রুত তথ্য জানান। কৃতিত্ব ভাগ করতে গিয়ে কে কাজ করেছেন তা আড়াল করা উচিত নয়।"}]'::jsonb),
  ('never-trust-too-much-friends', '002911f5dc201ebd17ab5df20d7200b2',
    '[{"id":"identify-the-risk","questionEn":"A close friend and a former competitor apply for the same team role. Which risk does this lesson most directly address?","questionBn":"এক ঘনিষ্ঠ বন্ধু ও এক সাবেক প্রতিদ্বন্দ্বী দলের একই পদের জন্য আবেদন করেছেন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["A request that ignores the other team''s workload gives it little reason to commit.","Personal relationships can bias judgments about who will perform well.","Familiar humor may not fit the norms or expectations of a new audience.","Announcing tentative terms can reduce room to negotiate or create premature expectations."],"optionsBn":["অন্য দলের কাজের চাপ উপেক্ষা করলে অনুরোধে সম্মত হওয়ার কারণ কম থাকে।","ব্যক্তিগত সম্পর্ক কে ভালো কাজ করবেন সেই বিচারে পক্ষপাত আনতে পারে।","পরিচিত রসিকতা নতুন শ্রোতার রীতি বা প্রত্যাশার সঙ্গে নাও মিলতে পারে।","অস্থায়ী শর্ত ঘোষণা করলে আলোচনার সুযোগ কমে বা অকালে প্রত্যাশা তৈরি হয়।"],"correctOption":1,"explanationEn":"Personal relationships can bias judgments about who will perform well.","explanationBn":"ব্যক্তিগত সম্পর্ক কে ভালো কাজ করবেন সেই বিচারে পক্ষপাত আনতে পারে।"},{"id":"apply-the-boundary","questionEn":"A close friend and a former competitor apply for the same team role. Which safeguard best prevents misusing this principle here?","questionBn":"এক ঘনিষ্ঠ বন্ধু ও এক সাবেক প্রতিদ্বন্দ্বী দলের একই পদের জন্য আবেদন করেছেন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Distinguish legitimate confidentiality from omissions that affect informed consent. Name when and to whom more can be disclosed.","Brevity works when the listener can act on what you said. Include dependencies or uncertainty if leaving them out would cause a bad decision.","A history of friendship or rivalry can explain an expectation, but neither predicts job performance without evidence. Apply conflict-of-interest rules before you score candidates.","A quick correction builds trust only when it is as visible as the original claim. Record the process that prevented the verification step."],"optionsBn":["বৈধ গোপনীয়তা ও অবহিত সম্মতিতে প্রভাব ফেলা তথ্য গোপনের পার্থক্য বুঝুন। কখন ও কাকে বিস্তারিত বলা যাবে তা জানান।","শ্রোতা আপনার কথা থেকে কাজ করতে পারলেই সংক্ষিপ্ততা কার্যকর। বাদ দিলে ভুল সিদ্ধান্ত হতে পারে এমন নির্ভরতা বা অনিশ্চয়তা জানান।","বন্ধুত্ব বা প্রতিদ্বন্দ্বিতা প্রত্যাশা ব্যাখ্যা করতে পারে, কিন্তু প্রমাণ ছাড়া কাজের মান বোঝায় না। নম্বর দেওয়ার আগে স্বার্থের সংঘাতের নিয়ম মানুন।","দ্রুত সংশোধনী তখনই আস্থা গড়ে যখন তা মূল দাবির মতোই দৃশ্যমান হয়। কোন প্রক্রিয়ায় যাচাই বাদ পড়েছিল তা নথিভুক্ত করুন।"],"correctOption":2,"explanationEn":"A history of friendship or rivalry can explain an expectation, but neither predicts job performance without evidence. Apply conflict-of-interest rules before you score candidates.","explanationBn":"বন্ধুত্ব বা প্রতিদ্বন্দ্বিতা প্রত্যাশা ব্যাখ্যা করতে পারে, কিন্তু প্রমাণ ছাড়া কাজের মান বোঝায় না। নম্বর দেওয়ার আগে স্বার্থের সংঘাতের নিয়ম মানুন।"}]'::jsonb),
  ('conceal-your-intentions', 'd7994f49b80b07fb4e6b5d07aee4daa1',
    '[{"id":"identify-the-risk","questionEn":"Your team is exploring a partnership before terms are ready to announce. Which risk does this lesson most directly address?","questionBn":"শর্ত চূড়ান্ত হওয়ার আগে আপনার দল একটি অংশীদারত্ব যাচাই করছে। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Announcing tentative terms can reduce room to negotiate or create premature expectations.","Repeated requests can consume goodwill without giving invitees a reason to engage.","A temporary truce may fail because the handoff still recreates the conflict.","A repetitive announcement schedule may make moves easy to anticipate."],"optionsBn":["অস্থায়ী শর্ত ঘোষণা করলে আলোচনার সুযোগ কমে বা অকালে প্রত্যাশা তৈরি হয়।","বারবার অনুরোধে সদিচ্ছা কমতে পারে, অথচ সাড়া দেওয়ার কারণ তৈরি হয় না।","সাময়িক সমঝোতা ভেঙে যেতে পারে, কারণ দায়িত্ব হস্তান্তরেই বিরোধ আবার তৈরি হয়।","একই সময়সূচিতে ঘোষণা দিলে পরবর্তী পদক্ষেপ অনুমান করা সহজ হয়।"],"correctOption":0,"explanationEn":"Announcing tentative terms can reduce room to negotiate or create premature expectations.","explanationBn":"অস্থায়ী শর্ত ঘোষণা করলে আলোচনার সুযোগ কমে বা অকালে প্রত্যাশা তৈরি হয়।"},{"id":"apply-the-boundary","questionEn":"Your team is exploring a partnership before terms are ready to announce. Which safeguard best prevents misusing this principle here?","questionBn":"শর্ত চূড়ান্ত হওয়ার আগে আপনার দল একটি অংশীদারত্ব যাচাই করছে। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Keep operational obligations predictable even when tactics change. People who rely on you need stable deadlines and a way to reach you.","Preserve independent judgment while meeting commitments already made. Tell people when and how a decision will actually be taken.","Concentrate effort where there is evidence of a bottleneck. Keep essential maintenance funded even when a pilot has a single focus.","Distinguish legitimate confidentiality from omissions that affect informed consent. Name when and to whom more can be disclosed."],"optionsBn":["কৌশল বদলালেও কাজের দায়বদ্ধতা স্থির রাখুন। নির্ভরশীল মানুষের স্থির সময়সীমা ও যোগাযোগের পথ দরকার।","আগে দেওয়া প্রতিশ্রুতি রেখে স্বাধীন বিচার বজায় রাখুন। সিদ্ধান্ত কখন ও কীভাবে হবে তা সংশ্লিষ্টদের জানান।","বাধার প্রমাণ যে জায়গায় আছে সেখানে প্রচেষ্টা দিন। পরীক্ষার লক্ষ্য একটি হলেও প্রয়োজনীয় রক্ষণাবেক্ষণের অর্থ রাখুন।","বৈধ গোপনীয়তা ও অবহিত সম্মতিতে প্রভাব ফেলা তথ্য গোপনের পার্থক্য বুঝুন। কখন ও কাকে বিস্তারিত বলা যাবে তা জানান।"],"correctOption":3,"explanationEn":"Distinguish legitimate confidentiality from omissions that affect informed consent. Name when and to whom more can be disclosed.","explanationBn":"বৈধ গোপনীয়তা ও অবহিত সম্মতিতে প্রভাব ফেলা তথ্য গোপনের পার্থক্য বুঝুন। কখন ও কাকে বিস্তারিত বলা যাবে তা জানান।"}]'::jsonb),
  ('always-say-less-than-necessary', '6fbee5f719681d69a1c980a92ebd656d',
    '[{"id":"identify-the-risk","questionEn":"A stakeholder asks why a delivery date moved during a crowded meeting. Which risk does this lesson most directly address?","questionBn":"একটি ব্যস্ত সভায় একজন অংশীজন কাজ জমা দেওয়ার তারিখ বদলের কারণ জানতে চান। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["An overlooked improvement may fail to reach the people who benefit from it.","Feedback collected without clear consent may undermine trust and compromise privacy.","Jargon can obscure assumptions that determine the estimate.","An overlong answer can bury the new deadline and the next action."],"optionsBn":["নজর এড়ানো উন্নতি যাঁদের কাজে লাগবে তাঁদের কাছে নাও পৌঁছাতে পারে।","স্পষ্ট সম্মতি ছাড়া মতামত সংগ্রহ করলে আস্থা ও গোপনীয়তা ক্ষতিগ্রস্ত হতে পারে।","দুর্বোধ্য পরিভাষা হিসাবের মূল অনুমানগুলো ঢেকে রাখতে পারে।","অতিরিক্ত দীর্ঘ উত্তরে নতুন সময়সীমা ও পরের কাজ চাপা পড়তে পারে।"],"correctOption":3,"explanationEn":"An overlong answer can bury the new deadline and the next action.","explanationBn":"অতিরিক্ত দীর্ঘ উত্তরে নতুন সময়সীমা ও পরের কাজ চাপা পড়তে পারে।"},{"id":"apply-the-boundary","questionEn":"A stakeholder asks why a delivery date moved during a crowded meeting. Which safeguard best prevents misusing this principle here?","questionBn":"একটি ব্যস্ত সভায় একজন অংশীজন কাজ জমা দেওয়ার তারিখ বদলের কারণ জানতে চান। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Brevity works when the listener can act on what you said. Include dependencies or uncertainty if leaving them out would cause a bad decision.","Basic questions test jargon and hidden assumptions. They are most useful when you can also check the answers against independent evidence.","A fluent presentation reduces friction for the audience. Keep enough of the preparation visible that others can reproduce the result.","An appealing picture can help people understand a goal. State uncertainty and invite people to verify progress against the milestones."],"optionsBn":["শ্রোতা আপনার কথা থেকে কাজ করতে পারলেই সংক্ষিপ্ততা কার্যকর। বাদ দিলে ভুল সিদ্ধান্ত হতে পারে এমন নির্ভরতা বা অনিশ্চয়তা জানান।","সহজ প্রশ্ন দুর্বোধ্য পরিভাষা ও গোপন অনুমান যাচাই করে। উত্তর স্বাধীন প্রমাণের সঙ্গে মিলিয়ে দেখতে পারলে এগুলো আরও কার্যকর।","সাবলীল উপস্থাপনা দর্শকের বোঝা সহজ করে। অন্যরা যেন ফল পুনরায় তৈরি করতে পারেন, সে জন্য যথেষ্ট প্রস্তুতি দৃশ্যমান রাখুন।","আকর্ষণীয় চিত্র লক্ষ্য বুঝতে সাহায্য করে। অনিশ্চয়তা জানান এবং লক্ষ্যচিহ্ন ধরে অগ্রগতি যাচাইয়ের সুযোগ দিন।"],"correctOption":0,"explanationEn":"Brevity works when the listener can act on what you said. Include dependencies or uncertainty if leaving them out would cause a bad decision.","explanationBn":"শ্রোতা আপনার কথা থেকে কাজ করতে পারলেই সংক্ষিপ্ততা কার্যকর। বাদ দিলে ভুল সিদ্ধান্ত হতে পারে এমন নির্ভরতা বা অনিশ্চয়তা জানান।"}]'::jsonb),
  ('so-much-depends-on-reputation-guard-it-with-your-life', '5fb7b0d99e22ba2e2e33d179ac4c0506',
    '[{"id":"identify-the-risk","questionEn":"A published report credits your team with a result it cannot substantiate. Which risk does this lesson most directly address?","questionBn":"একটি প্রকাশিত প্রতিবেদনে আপনার দলকে এমন ফলাফলের কৃতিত্ব দেওয়া হয়েছে যার প্রমাণ নেই। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Unlimited availability can exhaust the mentor and make access less dependable.","An undocumented exception makes accountability and consistent treatment difficult.","An unsupported public claim can undermine trust in verified work.","An image of effortless success can hide lessons others need to repeat the result."],"optionsBn":["সীমাহীন প্রাপ্যতা পরামর্শদাতাকে ক্লান্ত করে এবং সহায়তা পাওয়া অনিশ্চিত করে।","অলিখিত ব্যতিক্রম জবাবদিহি ও সমান আচরণ কঠিন করে।","প্রমাণহীন প্রকাশ্য দাবি যাচাইকৃত কাজের ওপরও আস্থা কমাতে পারে।","অনায়াস সাফল্যের ছবি ফল পুনরায় অর্জনের জন্য দরকারি শিক্ষা আড়াল করতে পারে।"],"correctOption":2,"explanationEn":"An unsupported public claim can undermine trust in verified work.","explanationBn":"প্রমাণহীন প্রকাশ্য দাবি যাচাইকৃত কাজের ওপরও আস্থা কমাতে পারে।"},{"id":"apply-the-boundary","questionEn":"A published report credits your team with a result it cannot substantiate. Which safeguard best prevents misusing this principle here?","questionBn":"একটি প্রকাশিত প্রতিবেদনে আপনার দলকে এমন ফলাফলের কৃতিত্ব দেওয়া হয়েছে যার প্রমাণ নেই। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["A specific mistake and what you learned make success explainable. Avoid false modesty, especially when another person''s contribution is at stake.","A quick correction builds trust only when it is as visible as the original claim. Record the process that prevented the verification step.","Visibility is valuable when the audience can verify what changed. Exaggeration may win attention once and make the next announcement less credible.","Coordination is a real contribution. Distinguish it from research, design, and delivery so the team can recognize each person''s work."],"optionsBn":["নির্দিষ্ট ভুল ও শেখা বিষয় বললে সাফল্য ব্যাখ্যাযোগ্য হয়। অন্যের অবদান জড়িত থাকলে বিশেষ করে কৃত্রিম বিনয় এড়ান।","দ্রুত সংশোধনী তখনই আস্থা গড়ে যখন তা মূল দাবির মতোই দৃশ্যমান হয়। কোন প্রক্রিয়ায় যাচাই বাদ পড়েছিল তা নথিভুক্ত করুন।","দর্শক পরিবর্তন যাচাই করতে পারলে দৃশ্যমানতা মূল্যবান। অতিরঞ্জন একবার নজর কাড়লেও পরের ঘোষণার বিশ্বাসযোগ্যতা কমায়।","সমন্বয়ও বাস্তব অবদান। গবেষণা, নকশা ও সরবরাহ থেকে তা আলাদা করে প্রতিটি মানুষের কাজ চিহ্নিত করুন।"],"correctOption":1,"explanationEn":"A quick correction builds trust only when it is as visible as the original claim. Record the process that prevented the verification step.","explanationBn":"দ্রুত সংশোধনী তখনই আস্থা গড়ে যখন তা মূল দাবির মতোই দৃশ্যমান হয়। কোন প্রক্রিয়ায় যাচাই বাদ পড়েছিল তা নথিভুক্ত করুন।"}]'::jsonb),
  ('court-attention-at-all-cost', '6b8df11137372197d0bb2cb1fdb7927d',
    '[{"id":"identify-the-risk","questionEn":"A useful accessibility fix is getting overlooked during a product launch. Which risk does this lesson most directly address?","questionBn":"পণ্য উদ্বোধনের সময় প্রবেশগম্যতার একটি কার্যকর উন্নতি নজর এড়িয়ে যাচ্ছে। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Feedback collected without clear consent may undermine trust and compromise privacy.","An overlooked improvement may fail to reach the people who benefit from it.","Jargon can obscure assumptions that determine the estimate.","Hiding the preparation can erase collaborators'' contributions and make results hard to reproduce."],"optionsBn":["স্পষ্ট সম্মতি ছাড়া মতামত সংগ্রহ করলে আস্থা ও গোপনীয়তা ক্ষতিগ্রস্ত হতে পারে।","নজর এড়ানো উন্নতি যাঁদের কাজে লাগবে তাঁদের কাছে নাও পৌঁছাতে পারে।","দুর্বোধ্য পরিভাষা হিসাবের মূল অনুমানগুলো ঢেকে রাখতে পারে।","প্রস্তুতি লুকালে সহকর্মীদের অবদান আড়াল হয় ও ফল পুনরায় তৈরি করা কঠিন হয়।"],"correctOption":1,"explanationEn":"An overlooked improvement may fail to reach the people who benefit from it.","explanationBn":"নজর এড়ানো উন্নতি যাঁদের কাজে লাগবে তাঁদের কাছে নাও পৌঁছাতে পারে।"},{"id":"apply-the-boundary","questionEn":"A useful accessibility fix is getting overlooked during a product launch. Which safeguard best prevents misusing this principle here?","questionBn":"পণ্য উদ্বোধনের সময় প্রবেশগম্যতার একটি কার্যকর উন্নতি নজর এড়িয়ে যাচ্ছে। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["A fluent presentation reduces friction for the audience. Keep enough of the preparation visible that others can reproduce the result.","An appealing picture can help people understand a goal. State uncertainty and invite people to verify progress against the milestones.","Visibility is valuable when the audience can verify what changed. Exaggeration may win attention once and make the next announcement less credible.","A memorable visual should make the relevant evidence easier to inspect. Label scale, missing data, and uncertainty when they affect interpretation."],"optionsBn":["সাবলীল উপস্থাপনা দর্শকের বোঝা সহজ করে। অন্যরা যেন ফল পুনরায় তৈরি করতে পারেন, সে জন্য যথেষ্ট প্রস্তুতি দৃশ্যমান রাখুন।","আকর্ষণীয় চিত্র লক্ষ্য বুঝতে সাহায্য করে। অনিশ্চয়তা জানান এবং লক্ষ্যচিহ্ন ধরে অগ্রগতি যাচাইয়ের সুযোগ দিন।","দর্শক পরিবর্তন যাচাই করতে পারলে দৃশ্যমানতা মূল্যবান। অতিরঞ্জন একবার নজর কাড়লেও পরের ঘোষণার বিশ্বাসযোগ্যতা কমায়।","স্মরণীয় দৃশ্য প্রাসঙ্গিক প্রমাণ যাচাই সহজ করবে। ব্যাখ্যায় প্রভাব ফেললে স্কেল, অনুপস্থিত তথ্য ও অনিশ্চয়তা চিহ্নিত করুন।"],"correctOption":2,"explanationEn":"Visibility is valuable when the audience can verify what changed. Exaggeration may win attention once and make the next announcement less credible.","explanationBn":"দর্শক পরিবর্তন যাচাই করতে পারলে দৃশ্যমানতা মূল্যবান। অতিরঞ্জন একবার নজর কাড়লেও পরের ঘোষণার বিশ্বাসযোগ্যতা কমায়।"}]'::jsonb),
  ('get-others-to-do-the-work-for-you', '23017bdd2da231e81ba2819e57e38218',
    '[{"id":"identify-the-risk","questionEn":"Several volunteers produce the material for a public presentation. Which risk does this lesson most directly address?","questionBn":"কয়েকজন স্বেচ্ছাসেবক একটি প্রকাশ্য উপস্থাপনার উপকরণ তৈরি করেছেন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Taking sole credit erodes contributors'' trust and willingness to help again.","Opinions about efficiency may hold up in debate even when the actual results differ.","A gift can influence judgment about an offer whose terms still need scrutiny.","Public embarrassment can make people defend a decision before hearing the evidence."],"optionsBn":["একাই কৃতিত্ব নিলে সহযোগীদের আস্থা ও আবার সাহায্য করার আগ্রহ কমে।","দক্ষতা নিয়ে মতামত তর্কে টিকে যেতে পারে, যদিও বাস্তব ফল ভিন্ন হয়।","উপহার এমন প্রস্তাবের বিচারকে প্রভাবিত করতে পারে, যার শর্ত এখনো যাচাই করা দরকার।","প্রকাশ্য বিব্রতকর অবস্থায় মানুষ প্রমাণ শোনার আগেই সিদ্ধান্তের সপক্ষে দাঁড়াতে পারে।"],"correctOption":0,"explanationEn":"Taking sole credit erodes contributors'' trust and willingness to help again.","explanationBn":"একাই কৃতিত্ব নিলে সহযোগীদের আস্থা ও আবার সাহায্য করার আগ্রহ কমে।"},{"id":"apply-the-boundary","questionEn":"Several volunteers produce the material for a public presentation. Which safeguard best prevents misusing this principle here?","questionBn":"কয়েকজন স্বেচ্ছাসেবক একটি প্রকাশ্য উপস্থাপনার উপকরণ তৈরি করেছেন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Tact improves the chance that evidence is heard. Use formal reporting in situations that require accountability or independent review.","Belonging can motivate cooperation, but demands for uncritical loyalty undermine judgment. Look for transparent claims, safe disagreement, and accountability.","Understanding someone''s concern helps you negotiate a workable agreement. Using private vulnerabilities as leverage will often destroy the trust the agreement needs.","Coordination is a real contribution. Distinguish it from research, design, and delivery so the team can recognize each person''s work."],"optionsBn":["কৌশলী উপস্থাপনা প্রমাণ শোনার সম্ভাবনা বাড়ায়। জবাবদিহি বা স্বাধীন পর্যালোচনা দরকার হলে আনুষ্ঠানিকভাবে জানান।","অন্তর্ভুক্তির অনুভূতি সহযোগিতা বাড়ায়, কিন্তু প্রশ্নহীন আনুগত্য বিচারশক্তি ক্ষয় করে। স্বচ্ছ দাবি, নিরাপদ ভিন্নমত ও জবাবদিহি দেখুন।","কারও উদ্বেগ বুঝলে কার্যকর সমঝোতা করা সহজ হয়। ব্যক্তিগত দুর্বলতা চাপ হিসেবে ব্যবহার করলে সমঝোতার জন্য দরকারি আস্থা নষ্ট হতে পারে।","সমন্বয়ও বাস্তব অবদান। গবেষণা, নকশা ও সরবরাহ থেকে তা আলাদা করে প্রতিটি মানুষের কাজ চিহ্নিত করুন।"],"correctOption":3,"explanationEn":"Coordination is a real contribution. Distinguish it from research, design, and delivery so the team can recognize each person''s work.","explanationBn":"সমন্বয়ও বাস্তব অবদান। গবেষণা, নকশা ও সরবরাহ থেকে তা আলাদা করে প্রতিটি মানুষের কাজ চিহ্নিত করুন।"}]'::jsonb),
  ('make-other-people-come-to-you', '4fab9c4214fd9ca7cf6363989a3bbb36',
    '[{"id":"identify-the-risk","questionEn":"Prospective collaborators ignore repeated meeting invitations. Which risk does this lesson most directly address?","questionBn":"সম্ভাব্য সহযোগীরা বারবার সভার আমন্ত্রণ উপেক্ষা করছেন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["A temporary truce may fail because the handoff still recreates the conflict.","A repetitive announcement schedule may make moves easy to anticipate.","An early promise of exclusive support can undermine independent evaluation.","Repeated requests can consume goodwill without giving invitees a reason to engage."],"optionsBn":["সাময়িক সমঝোতা ভেঙে যেতে পারে, কারণ দায়িত্ব হস্তান্তরেই বিরোধ আবার তৈরি হয়।","একই সময়সূচিতে ঘোষণা দিলে পরবর্তী পদক্ষেপ অনুমান করা সহজ হয়।","আগেই একচেটিয়া সমর্থনের প্রতিশ্রুতি দিলে স্বাধীন মূল্যায়ন দুর্বল হয়।","বারবার অনুরোধে সদিচ্ছা কমতে পারে, অথচ সাড়া দেওয়ার কারণ তৈরি হয় না।"],"correctOption":3,"explanationEn":"Repeated requests can consume goodwill without giving invitees a reason to engage.","explanationBn":"বারবার অনুরোধে সদিচ্ছা কমতে পারে, অথচ সাড়া দেওয়ার কারণ তৈরি হয় না।"},{"id":"apply-the-boundary","questionEn":"Prospective collaborators ignore repeated meeting invitations. Which safeguard best prevents misusing this principle here?","questionBn":"সম্ভাব্য সহযোগীরা বারবার সভার আমন্ত্রণ উপেক্ষা করছেন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["An invitation should have value even if the recipient declines the larger proposal. Avoid hidden obligations that make the first interaction feel deceptive.","Preserve independent judgment while meeting commitments already made. Tell people when and how a decision will actually be taken.","Concentrate effort where there is evidence of a bottleneck. Keep essential maintenance funded even when a pilot has a single focus.","Move quickly when the decision is reversible and the risk bounded. Decisions exposing others to permanent harm need stronger review."],"optionsBn":["বড় প্রস্তাব প্রত্যাখ্যান করলেও আমন্ত্রণটি প্রাপকের কাজে লাগা উচিত। প্রথম যোগাযোগকে প্রতারণামূলক করে এমন গোপন শর্ত এড়ান।","আগে দেওয়া প্রতিশ্রুতি রেখে স্বাধীন বিচার বজায় রাখুন। সিদ্ধান্ত কখন ও কীভাবে হবে তা সংশ্লিষ্টদের জানান।","বাধার প্রমাণ যে জায়গায় আছে সেখানে প্রচেষ্টা দিন। পরীক্ষার লক্ষ্য একটি হলেও প্রয়োজনীয় রক্ষণাবেক্ষণের অর্থ রাখুন।","সিদ্ধান্ত ফিরিয়ে নেওয়া গেলে ও ঝুঁকি সীমিত থাকলে দ্রুত এগোন। অন্যদের স্থায়ী ক্ষতির ঝুঁকি থাকলে কঠোর পর্যালোচনা দরকার।"],"correctOption":0,"explanationEn":"An invitation should have value even if the recipient declines the larger proposal. Avoid hidden obligations that make the first interaction feel deceptive.","explanationBn":"বড় প্রস্তাব প্রত্যাখ্যান করলেও আমন্ত্রণটি প্রাপকের কাজে লাগা উচিত। প্রথম যোগাযোগকে প্রতারণামূলক করে এমন গোপন শর্ত এড়ান।"}]'::jsonb),
  ('win-through-your-actions-never-through-argument', 'b3816d12bdc577a180d2fe8b804c898b',
    '[{"id":"identify-the-risk","questionEn":"Two coworkers disagree about which support template saves more time. Which risk does this lesson most directly address?","questionBn":"কোন সহায়তা টেমপ্লেটে বেশি সময় বাঁচে তা নিয়ে দুই সহকর্মী একমত নন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["A gift can influence judgment about an offer whose terms still need scrutiny.","Public embarrassment can make people defend a decision before hearing the evidence.","Opinions about efficiency may hold up in debate even when the actual results differ.","Discouraging questions can make loyalty replace independent judgment."],"optionsBn":["উপহার এমন প্রস্তাবের বিচারকে প্রভাবিত করতে পারে, যার শর্ত এখনো যাচাই করা দরকার।","প্রকাশ্য বিব্রতকর অবস্থায় মানুষ প্রমাণ শোনার আগেই সিদ্ধান্তের সপক্ষে দাঁড়াতে পারে।","দক্ষতা নিয়ে মতামত তর্কে টিকে যেতে পারে, যদিও বাস্তব ফল ভিন্ন হয়।","প্রশ্ন নিরুৎসাহিত করলে স্বাধীন বিচারের জায়গায় আনুগত্য চলে আসতে পারে।"],"correctOption":2,"explanationEn":"Opinions about efficiency may hold up in debate even when the actual results differ.","explanationBn":"দক্ষতা নিয়ে মতামত তর্কে টিকে যেতে পারে, যদিও বাস্তব ফল ভিন্ন হয়।"},{"id":"apply-the-boundary","questionEn":"Two coworkers disagree about which support template saves more time. Which safeguard best prevents misusing this principle here?","questionBn":"কোন সহায়তা টেমপ্লেটে বেশি সময় বাঁচে তা নিয়ে দুই সহকর্মী একমত নন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Belonging can motivate cooperation, but demands for uncritical loyalty undermine judgment. Look for transparent claims, safe disagreement, and accountability.","Define the comparison before you see the numbers. Include error rate and accessibility alongside speed so the faster template does not disguise worse service.","Understanding someone''s concern helps you negotiate a workable agreement. Using private vulnerabilities as leverage will often destroy the trust the agreement needs.","Concern is information about a real implementation constraint. Demonstrate that you heard it by showing what changed and why."],"optionsBn":["অন্তর্ভুক্তির অনুভূতি সহযোগিতা বাড়ায়, কিন্তু প্রশ্নহীন আনুগত্য বিচারশক্তি ক্ষয় করে। স্বচ্ছ দাবি, নিরাপদ ভিন্নমত ও জবাবদিহি দেখুন।","ফল দেখার আগে তুলনার মানদণ্ড ঠিক করুন। গতির পাশাপাশি ভুলের হার ও প্রবেশগম্যতা ধরুন যাতে দ্রুততর টেমপ্লেট খারাপ সেবা ঢেকে না দেয়।","কারও উদ্বেগ বুঝলে কার্যকর সমঝোতা করা সহজ হয়। ব্যক্তিগত দুর্বলতা চাপ হিসেবে ব্যবহার করলে সমঝোতার জন্য দরকারি আস্থা নষ্ট হতে পারে।","উদ্বেগ বাস্তবায়নের প্রকৃত সীমার তথ্য দেয়। কী বদলেছে ও কেন তা দেখিয়ে বোঝান যে আপনি কথা শুনেছেন।"],"correctOption":1,"explanationEn":"Define the comparison before you see the numbers. Include error rate and accessibility alongside speed so the faster template does not disguise worse service.","explanationBn":"ফল দেখার আগে তুলনার মানদণ্ড ঠিক করুন। গতির পাশাপাশি ভুলের হার ও প্রবেশগম্যতা ধরুন যাতে দ্রুততর টেমপ্লেট খারাপ সেবা ঢেকে না দেয়।"}]'::jsonb),
  ('infection-avoid-the-unhappy-and-unlucky', '1dcf695b1c8f0e2578129c68174ecb24',
    '[{"id":"identify-the-risk","questionEn":"Chronic venting is crowding out work in a team chat. Which risk does this lesson most directly address?","questionBn":"দলের চ্যাটে লাগাতার অভিযোগের কারণে কাজের আলোচনা চাপা পড়ছে। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Isolation cuts off early warnings and leaves the team responding late.","Recurring venting can crowd out coordination without solving the source of distress.","Old habits can make colleagues keep treating a new manager as an individual contributor.","A meeting without a clear process can allow status to determine whose concerns are heard."],"optionsBn":["বিচ্ছিন্নতায় আগাম সতর্কতা পৌঁছায় না, ফলে দল দেরিতে সাড়া দেয়।","বারবার অভিযোগে সমন্বয়ের আলোচনা চাপা পড়ে, অথচ কষ্টের উৎস দূর হয় না।","পুরোনো অভ্যাসে সহকর্মীরা নতুন ব্যবস্থাপককেও স্বতন্ত্র কর্মী হিসেবে দেখতে পারেন।","স্পষ্ট পদ্ধতি না থাকলে কার কথা শোনা হবে তা সভায় পদমর্যাদা নির্ধারণ করতে পারে।"],"correctOption":1,"explanationEn":"Recurring venting can crowd out coordination without solving the source of distress.","explanationBn":"বারবার অভিযোগে সমন্বয়ের আলোচনা চাপা পড়ে, অথচ কষ্টের উৎস দূর হয় না।"},{"id":"apply-the-boundary","questionEn":"Chronic venting is crowding out work in a team chat. Which safeguard best prevents misusing this principle here?","questionBn":"দলের চ্যাটে লাগাতার অভিযোগের কারণে কাজের আলোচনা চাপা পড়ছে। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Calm authority comes from owning a decision process. Make space for relevant objections, especially from people with lower status.","Stop investing attention after the answer is settled, but keep lessons that improve the next attempt. Persistent problems still need a responsible escalation path.","The useful boundary is about recurring behavior and its effect on the team. Distress by itself calls for empathy and appropriate support.","Calculate the cost across the whole relationship. Check exclusivity, future dependence, and data access alongside the headline price."],"optionsBn":["শান্ত কর্তৃত্ব আসে সিদ্ধান্তের প্রক্রিয়ার দায় নেওয়া থেকে। প্রাসঙ্গিক আপত্তির সুযোগ রাখুন, বিশেষ করে কম ক্ষমতাসম্পন্ন মানুষের জন্য।","সিদ্ধান্ত চূড়ান্ত হলে সময় ব্যয় থামান, তবে পরের চেষ্টা উন্নত করে এমন শিক্ষা রাখুন। চলমান সমস্যার জন্য দায়িত্বপূর্ণভাবে বিষয় তোলার পথ দরকার।","সীমা টানার কারণ হলো পুনরাবৃত্ত আচরণ ও দলের ওপর তার প্রভাব। কষ্টে থাকা মানুষের প্রতি সহমর্মিতা ও উপযুক্ত সহায়তা দিন।","পুরো সম্পর্কের ব্যয় হিসাব করুন। ঘোষিত দামের পাশাপাশি একচেটিয়া শর্ত, ভবিষ্যৎ নির্ভরতা ও তথ্যের প্রবেশাধিকার যাচাই করুন।"],"correctOption":2,"explanationEn":"The useful boundary is about recurring behavior and its effect on the team. Distress by itself calls for empathy and appropriate support.","explanationBn":"সীমা টানার কারণ হলো পুনরাবৃত্ত আচরণ ও দলের ওপর তার প্রভাব। কষ্টে থাকা মানুষের প্রতি সহমর্মিতা ও উপযুক্ত সহায়তা দিন।"}]'::jsonb),
  ('learn-to-keep-people-dependent-on-you', '4060ce982c649491473e30dcbfb7f7bf',
    '[{"id":"identify-the-risk","questionEn":"One specialist maintains a tool everyone needs. Which risk does this lesson most directly address?","questionBn":"সবার প্রয়োজন এমন একটি সরঞ্জাম একজন বিশেষজ্ঞ একাই রক্ষণাবেক্ষণ করেন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["An absence or departure can interrupt an essential service when knowledge is concentrated.","Visible contributions may be mistaken for a challenge to the lead''s status.","A gift can influence judgment about an offer whose terms still need scrutiny.","A request that ignores the other team''s workload gives it little reason to commit."],"optionsBn":["জ্ঞান একজনের হাতে কেন্দ্রীভূত থাকলে তাঁর অনুপস্থিতি বা প্রস্থানে জরুরি সেবা বন্ধ হতে পারে।","প্রকাশ্য অবদানকে নেতার মর্যাদার প্রতি চ্যালেঞ্জ বলে ভুল বোঝা হতে পারে।","উপহার এমন প্রস্তাবের বিচারকে প্রভাবিত করতে পারে, যার শর্ত এখনো যাচাই করা দরকার।","অন্য দলের কাজের চাপ উপেক্ষা করলে অনুরোধে সম্মত হওয়ার কারণ কম থাকে।"],"correctOption":0,"explanationEn":"An absence or departure can interrupt an essential service when knowledge is concentrated.","explanationBn":"জ্ঞান একজনের হাতে কেন্দ্রীভূত থাকলে তাঁর অনুপস্থিতি বা প্রস্থানে জরুরি সেবা বন্ধ হতে পারে।"},{"id":"apply-the-boundary","questionEn":"One specialist maintains a tool everyone needs. Which safeguard best prevents misusing this principle here?","questionBn":"সবার প্রয়োজন এমন একটি সরঞ্জাম একজন বিশেষজ্ঞ একাই রক্ষণাবেক্ষণ করেন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["A mutual benefit must be concrete enough for the other team to evaluate. Ask what they would count as a worthwhile return.","Collect observations people agreed to share. Limit personal information and keep feedback anonymous when its disclosure could carry a cost.","A durable settlement removes the circumstances that recreate the conflict. Retaliation leaves the root cause in place and adds another dispute.","Expertise creates durable influence when people choose to seek it. A single point of failure creates short-term dependence and long-term risk."],"optionsBn":["পারস্পরিক সুবিধা এমন নির্দিষ্ট হওয়া চাই যাতে অন্য দল তা বিচার করতে পারে। তাদের কাছে কোন ফল লাভজনক হবে জিজ্ঞাসা করুন।","মানুষ যে তথ্য ভাগ করতে সম্মত হয়েছে তা সংগ্রহ করুন। ব্যক্তিগত তথ্য সীমিত রাখুন এবং প্রকাশে ক্ষতির আশঙ্কা থাকলে মতামত নামবিহীন রাখুন।","টেকসই সমাধান সংঘাত আবার তৈরি হওয়ার পরিস্থিতি দূর করে। প্রতিশোধ মূল কারণ রেখে নতুন বিরোধ যোগ করে।","মানুষ স্বেচ্ছায় দক্ষতার সাহায্য চাইলে দীর্ঘস্থায়ী প্রভাব তৈরি হয়। একমাত্র নির্ভরতার জায়গা স্বল্পমেয়াদি নির্ভরতা ও দীর্ঘমেয়াদি ঝুঁকি তৈরি করে।"],"correctOption":3,"explanationEn":"Expertise creates durable influence when people choose to seek it. A single point of failure creates short-term dependence and long-term risk.","explanationBn":"মানুষ স্বেচ্ছায় দক্ষতার সাহায্য চাইলে দীর্ঘস্থায়ী প্রভাব তৈরি হয়। একমাত্র নির্ভরতার জায়গা স্বল্পমেয়াদি নির্ভরতা ও দীর্ঘমেয়াদি ঝুঁকি তৈরি করে।"}]'::jsonb),
  ('use-selective-honesty-and-generosity', 'd8318207ec8d9f14d274d672c8769d0d',
    '[{"id":"identify-the-risk","questionEn":"A new vendor gives your team a generous gift before procurement. Which risk does this lesson most directly address?","questionBn":"ক্রয়ের সিদ্ধান্তের আগে নতুন বিক্রেতা আপনার দলকে মূল্যবান উপহার দিয়েছেন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Public embarrassment can make people defend a decision before hearing the evidence.","Discouraging questions can make loyalty replace independent judgment.","A process may meet its formal goal while making someone''s contribution harder to see.","A gift can influence judgment about an offer whose terms still need scrutiny."],"optionsBn":["প্রকাশ্য বিব্রতকর অবস্থায় মানুষ প্রমাণ শোনার আগেই সিদ্ধান্তের সপক্ষে দাঁড়াতে পারে।","প্রশ্ন নিরুৎসাহিত করলে স্বাধীন বিচারের জায়গায় আনুগত্য চলে আসতে পারে।","প্রক্রিয়া আনুষ্ঠানিক লক্ষ্য পূরণ করলেও কারও অবদান দেখা কঠিন করে দিতে পারে।","উপহার এমন প্রস্তাবের বিচারকে প্রভাবিত করতে পারে, যার শর্ত এখনো যাচাই করা দরকার।"],"correctOption":3,"explanationEn":"A gift can influence judgment about an offer whose terms still need scrutiny.","explanationBn":"উপহার এমন প্রস্তাবের বিচারকে প্রভাবিত করতে পারে, যার শর্ত এখনো যাচাই করা দরকার।"},{"id":"apply-the-boundary","questionEn":"A new vendor gives your team a generous gift before procurement. Which safeguard best prevents misusing this principle here?","questionBn":"ক্রয়ের সিদ্ধান্তের আগে নতুন বিক্রেতা আপনার দলকে মূল্যবান উপহার দিয়েছেন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["An honest disclosure or generous gesture is evidence of that act alone. Check the broader deal, including price, conditions, and obligations.","Understanding someone''s concern helps you negotiate a workable agreement. Using private vulnerabilities as leverage will often destroy the trust the agreement needs.","Concern is information about a real implementation constraint. Demonstrate that you heard it by showing what changed and why.","Coordination is a real contribution. Distinguish it from research, design, and delivery so the team can recognize each person''s work."],"optionsBn":["সৎ স্বীকারোক্তি বা উদারতা শুধু সেই কাজের প্রমাণ। দাম, শর্ত ও দায়বদ্ধতাসহ পুরো চুক্তি যাচাই করুন।","কারও উদ্বেগ বুঝলে কার্যকর সমঝোতা করা সহজ হয়। ব্যক্তিগত দুর্বলতা চাপ হিসেবে ব্যবহার করলে সমঝোতার জন্য দরকারি আস্থা নষ্ট হতে পারে।","উদ্বেগ বাস্তবায়নের প্রকৃত সীমার তথ্য দেয়। কী বদলেছে ও কেন তা দেখিয়ে বোঝান যে আপনি কথা শুনেছেন।","সমন্বয়ও বাস্তব অবদান। গবেষণা, নকশা ও সরবরাহ থেকে তা আলাদা করে প্রতিটি মানুষের কাজ চিহ্নিত করুন।"],"correctOption":0,"explanationEn":"An honest disclosure or generous gesture is evidence of that act alone. Check the broader deal, including price, conditions, and obligations.","explanationBn":"সৎ স্বীকারোক্তি বা উদারতা শুধু সেই কাজের প্রমাণ। দাম, শর্ত ও দায়বদ্ধতাসহ পুরো চুক্তি যাচাই করুন।"}]'::jsonb),
  ('when-asking-for-help-appeal-to-self-interest', 'e5e76498bdb3052f9eea32a08f12c048',
    '[{"id":"identify-the-risk","questionEn":"You need another department to lend staff for a pilot. Which risk does this lesson most directly address?","questionBn":"পরীক্ষামূলক উদ্যোগের জন্য অন্য বিভাগ থেকে কর্মী দরকার। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Familiar humor may not fit the norms or expectations of a new audience.","Personal relationships can bias judgments about who will perform well.","A request that ignores the other team''s workload gives it little reason to commit.","Feedback collected without clear consent may undermine trust and compromise privacy."],"optionsBn":["পরিচিত রসিকতা নতুন শ্রোতার রীতি বা প্রত্যাশার সঙ্গে নাও মিলতে পারে।","ব্যক্তিগত সম্পর্ক কে ভালো কাজ করবেন সেই বিচারে পক্ষপাত আনতে পারে।","অন্য দলের কাজের চাপ উপেক্ষা করলে অনুরোধে সম্মত হওয়ার কারণ কম থাকে।","স্পষ্ট সম্মতি ছাড়া মতামত সংগ্রহ করলে আস্থা ও গোপনীয়তা ক্ষতিগ্রস্ত হতে পারে।"],"correctOption":2,"explanationEn":"A request that ignores the other team''s workload gives it little reason to commit.","explanationBn":"অন্য দলের কাজের চাপ উপেক্ষা করলে অনুরোধে সম্মত হওয়ার কারণ কম থাকে।"},{"id":"apply-the-boundary","questionEn":"You need another department to lend staff for a pilot. Which safeguard best prevents misusing this principle here?","questionBn":"পরীক্ষামূলক উদ্যোগের জন্য অন্য বিভাগ থেকে কর্মী দরকার। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Collect observations people agreed to share. Limit personal information and keep feedback anonymous when its disclosure could carry a cost.","A mutual benefit must be concrete enough for the other team to evaluate. Ask what they would count as a worthwhile return.","A durable settlement removes the circumstances that recreate the conflict. Retaliation leaves the root cause in place and adds another dispute.","Predictable availability makes a boundary workable for others. Absence that interrupts promised support erodes the respect you wanted to preserve."],"optionsBn":["মানুষ যে তথ্য ভাগ করতে সম্মত হয়েছে তা সংগ্রহ করুন। ব্যক্তিগত তথ্য সীমিত রাখুন এবং প্রকাশে ক্ষতির আশঙ্কা থাকলে মতামত নামবিহীন রাখুন।","পারস্পরিক সুবিধা এমন নির্দিষ্ট হওয়া চাই যাতে অন্য দল তা বিচার করতে পারে। তাদের কাছে কোন ফল লাভজনক হবে জিজ্ঞাসা করুন।","টেকসই সমাধান সংঘাত আবার তৈরি হওয়ার পরিস্থিতি দূর করে। প্রতিশোধ মূল কারণ রেখে নতুন বিরোধ যোগ করে।","কখন পাওয়া যাবে জানা থাকলে অন্যরা সীমা মেনে কাজ করতে পারেন। প্রতিশ্রুত সহায়তা বন্ধ করা অনুপস্থিতি সম্মান ক্ষয় করে।"],"correctOption":1,"explanationEn":"A mutual benefit must be concrete enough for the other team to evaluate. Ask what they would count as a worthwhile return.","explanationBn":"পারস্পরিক সুবিধা এমন নির্দিষ্ট হওয়া চাই যাতে অন্য দল তা বিচার করতে পারে। তাদের কাছে কোন ফল লাভজনক হবে জিজ্ঞাসা করুন।"}]'::jsonb),
  ('pose-as-a-friend-work-as-a-spy', '51a56c4f03c0dba12c8471fbebaffacf',
    '[{"id":"identify-the-risk","questionEn":"You want to understand why people avoid a new service. Which risk does this lesson most directly address?","questionBn":"মানুষ কেন নতুন সেবাটি এড়িয়ে যাচ্ছে তা জানতে চান। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Jargon can obscure assumptions that determine the estimate.","Feedback collected without clear consent may undermine trust and compromise privacy.","Hiding the preparation can erase collaborators'' contributions and make results hard to reproduce.","An appealing promise can hide uncertainty about cost, time, and feasibility."],"optionsBn":["দুর্বোধ্য পরিভাষা হিসাবের মূল অনুমানগুলো ঢেকে রাখতে পারে।","স্পষ্ট সম্মতি ছাড়া মতামত সংগ্রহ করলে আস্থা ও গোপনীয়তা ক্ষতিগ্রস্ত হতে পারে।","প্রস্তুতি লুকালে সহকর্মীদের অবদান আড়াল হয় ও ফল পুনরায় তৈরি করা কঠিন হয়।","আকর্ষণীয় প্রতিশ্রুতি খরচ, সময় ও বাস্তবসম্ভাব্যতার অনিশ্চয়তা আড়াল করতে পারে।"],"correctOption":1,"explanationEn":"Feedback collected without clear consent may undermine trust and compromise privacy.","explanationBn":"স্পষ্ট সম্মতি ছাড়া মতামত সংগ্রহ করলে আস্থা ও গোপনীয়তা ক্ষতিগ্রস্ত হতে পারে।"},{"id":"apply-the-boundary","questionEn":"You want to understand why people avoid a new service. Which safeguard best prevents misusing this principle here?","questionBn":"মানুষ কেন নতুন সেবাটি এড়িয়ে যাচ্ছে তা জানতে চান। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["An appealing picture can help people understand a goal. State uncertainty and invite people to verify progress against the milestones.","A memorable visual should make the relevant evidence easier to inspect. Label scale, missing data, and uncertainty when they affect interpretation.","Collect observations people agreed to share. Limit personal information and keep feedback anonymous when its disclosure could carry a cost.","Accurate reflection can defuse misunderstanding. Imitation used to ridicule the other party often worsens it."],"optionsBn":["আকর্ষণীয় চিত্র লক্ষ্য বুঝতে সাহায্য করে। অনিশ্চয়তা জানান এবং লক্ষ্যচিহ্ন ধরে অগ্রগতি যাচাইয়ের সুযোগ দিন।","স্মরণীয় দৃশ্য প্রাসঙ্গিক প্রমাণ যাচাই সহজ করবে। ব্যাখ্যায় প্রভাব ফেললে স্কেল, অনুপস্থিত তথ্য ও অনিশ্চয়তা চিহ্নিত করুন।","মানুষ যে তথ্য ভাগ করতে সম্মত হয়েছে তা সংগ্রহ করুন। ব্যক্তিগত তথ্য সীমিত রাখুন এবং প্রকাশে ক্ষতির আশঙ্কা থাকলে মতামত নামবিহীন রাখুন।","নির্ভুলভাবে বক্তব্য ফিরিয়ে বললে ভুল বোঝাবুঝি কমে। বিদ্রূপের জন্য অনুকরণ করলে তা প্রায়ই বাড়ে।"],"correctOption":2,"explanationEn":"Collect observations people agreed to share. Limit personal information and keep feedback anonymous when its disclosure could carry a cost.","explanationBn":"মানুষ যে তথ্য ভাগ করতে সম্মত হয়েছে তা সংগ্রহ করুন। ব্যক্তিগত তথ্য সীমিত রাখুন এবং প্রকাশে ক্ষতির আশঙ্কা থাকলে মতামত নামবিহীন রাখুন।"}]'::jsonb),
  ('crush-your-enemy-totally', '7134a8cbe7497991d1be8c15552b033a',
    '[{"id":"identify-the-risk","questionEn":"A recurring dispute returns every time a shift changes. Which risk does this lesson most directly address?","questionBn":"প্রতি পালাবদলে একই বিরোধ আবার দেখা দিচ্ছে। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["A temporary truce may fail because the handoff still recreates the conflict.","A repetitive announcement schedule may make moves easy to anticipate.","An early promise of exclusive support can undermine independent evaluation.","Spreading a small budget across many problems may leave the main bottleneck untouched."],"optionsBn":["সাময়িক সমঝোতা ভেঙে যেতে পারে, কারণ দায়িত্ব হস্তান্তরেই বিরোধ আবার তৈরি হয়।","একই সময়সূচিতে ঘোষণা দিলে পরবর্তী পদক্ষেপ অনুমান করা সহজ হয়।","আগেই একচেটিয়া সমর্থনের প্রতিশ্রুতি দিলে স্বাধীন মূল্যায়ন দুর্বল হয়।","অল্প বাজেট অনেক সমস্যায় ভাগ করলে মূল বাধা থেকেই যেতে পারে।"],"correctOption":0,"explanationEn":"A temporary truce may fail because the handoff still recreates the conflict.","explanationBn":"সাময়িক সমঝোতা ভেঙে যেতে পারে, কারণ দায়িত্ব হস্তান্তরেই বিরোধ আবার তৈরি হয়।"},{"id":"apply-the-boundary","questionEn":"A recurring dispute returns every time a shift changes. Which safeguard best prevents misusing this principle here?","questionBn":"প্রতি পালাবদলে একই বিরোধ আবার দেখা দিচ্ছে। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Concentrate effort where there is evidence of a bottleneck. Keep essential maintenance funded even when a pilot has a single focus.","Move quickly when the decision is reversible and the risk bounded. Decisions exposing others to permanent harm need stronger review.","A launch is only one point in the work. Set responsibilities and evidence requirements for delivery, maintenance, and recovery before committing.","A durable settlement removes the circumstances that recreate the conflict. Retaliation leaves the root cause in place and adds another dispute."],"optionsBn":["বাধার প্রমাণ যে জায়গায় আছে সেখানে প্রচেষ্টা দিন। পরীক্ষার লক্ষ্য একটি হলেও প্রয়োজনীয় রক্ষণাবেক্ষণের অর্থ রাখুন।","সিদ্ধান্ত ফিরিয়ে নেওয়া গেলে ও ঝুঁকি সীমিত থাকলে দ্রুত এগোন। অন্যদের স্থায়ী ক্ষতির ঝুঁকি থাকলে কঠোর পর্যালোচনা দরকার।","উদ্বোধন কাজের একটি মাত্র ধাপ। প্রতিশ্রুতির আগে সরবরাহ, রক্ষণাবেক্ষণ ও পুনরুদ্ধারের দায়িত্ব এবং প্রমাণের শর্ত ঠিক করুন।","টেকসই সমাধান সংঘাত আবার তৈরি হওয়ার পরিস্থিতি দূর করে। প্রতিশোধ মূল কারণ রেখে নতুন বিরোধ যোগ করে।"],"correctOption":3,"explanationEn":"A durable settlement removes the circumstances that recreate the conflict. Retaliation leaves the root cause in place and adds another dispute.","explanationBn":"টেকসই সমাধান সংঘাত আবার তৈরি হওয়ার পরিস্থিতি দূর করে। প্রতিশোধ মূল কারণ রেখে নতুন বিরোধ যোগ করে।"}]'::jsonb),
  ('use-absence-to-increase-respect-and-honor', 'ef0284fab8a936d5c85639cabae7d523',
    '[{"id":"identify-the-risk","questionEn":"A mentor is overwhelmed by ad hoc requests. Which risk does this lesson most directly address?","questionBn":"অনিয়মিত অনুরোধের চাপে একজন পরামর্শদাতা হিমশিম খাচ্ছেন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["An undocumented exception makes accountability and consistent treatment difficult.","An image of effortless success can hide lessons others need to repeat the result.","An unsupported public claim can undermine trust in verified work.","Unlimited availability can exhaust the mentor and make access less dependable."],"optionsBn":["অলিখিত ব্যতিক্রম জবাবদিহি ও সমান আচরণ কঠিন করে।","অনায়াস সাফল্যের ছবি ফল পুনরায় অর্জনের জন্য দরকারি শিক্ষা আড়াল করতে পারে।","প্রমাণহীন প্রকাশ্য দাবি যাচাইকৃত কাজের ওপরও আস্থা কমাতে পারে।","সীমাহীন প্রাপ্যতা পরামর্শদাতাকে ক্লান্ত করে এবং সহায়তা পাওয়া অনিশ্চিত করে।"],"correctOption":3,"explanationEn":"Unlimited availability can exhaust the mentor and make access less dependable.","explanationBn":"সীমাহীন প্রাপ্যতা পরামর্শদাতাকে ক্লান্ত করে এবং সহায়তা পাওয়া অনিশ্চিত করে।"},{"id":"apply-the-boundary","questionEn":"A mentor is overwhelmed by ad hoc requests. Which safeguard best prevents misusing this principle here?","questionBn":"অনিয়মিত অনুরোধের চাপে একজন পরামর্শদাতা হিমশিম খাচ্ছেন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Predictable availability makes a boundary workable for others. Absence that interrupts promised support erodes the respect you wanted to preserve.","A quick correction builds trust only when it is as visible as the original claim. Record the process that prevented the verification step.","Keep operational obligations predictable even when tactics change. People who rely on you need stable deadlines and a way to reach you.","More contacts help only when useful information can travel both ways. Give partner teams a clear path for reporting problems."],"optionsBn":["কখন পাওয়া যাবে জানা থাকলে অন্যরা সীমা মেনে কাজ করতে পারেন। প্রতিশ্রুত সহায়তা বন্ধ করা অনুপস্থিতি সম্মান ক্ষয় করে।","দ্রুত সংশোধনী তখনই আস্থা গড়ে যখন তা মূল দাবির মতোই দৃশ্যমান হয়। কোন প্রক্রিয়ায় যাচাই বাদ পড়েছিল তা নথিভুক্ত করুন।","কৌশল বদলালেও কাজের দায়বদ্ধতা স্থির রাখুন। নির্ভরশীল মানুষের স্থির সময়সীমা ও যোগাযোগের পথ দরকার।","উপকারী তথ্য দুই দিকেই চললে যোগাযোগ বাড়ানোর লাভ আছে। অন্য দলকে সমস্যা জানানোর স্পষ্ট পথ দিন।"],"correctOption":0,"explanationEn":"Predictable availability makes a boundary workable for others. Absence that interrupts promised support erodes the respect you wanted to preserve.","explanationBn":"কখন পাওয়া যাবে জানা থাকলে অন্যরা সীমা মেনে কাজ করতে পারেন। প্রতিশ্রুত সহায়তা বন্ধ করা অনুপস্থিতি সম্মান ক্ষয় করে।"}]'::jsonb),
  ('keep-others-in-suspended-terror', '66ad41f42fd3a756f97ce7a0c9d2f0eb',
    '[{"id":"identify-the-risk","questionEn":"A competitor anticipates every public product announcement. Which risk does this lesson most directly address?","questionBn":"এক প্রতিদ্বন্দ্বী প্রতিটি প্রকাশ্য পণ্য ঘোষণার আগেই তা অনুমান করে ফেলেন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["An early promise of exclusive support can undermine independent evaluation.","Spreading a small budget across many problems may leave the main bottleneck untouched.","A repetitive announcement schedule may make moves easy to anticipate.","Continuing to debate a reversible trial can delay learning without reducing much risk."],"optionsBn":["আগেই একচেটিয়া সমর্থনের প্রতিশ্রুতি দিলে স্বাধীন মূল্যায়ন দুর্বল হয়।","অল্প বাজেট অনেক সমস্যায় ভাগ করলে মূল বাধা থেকেই যেতে পারে।","একই সময়সূচিতে ঘোষণা দিলে পরবর্তী পদক্ষেপ অনুমান করা সহজ হয়।","ফিরিয়ে নেওয়া যায় এমন পরীক্ষা নিয়ে তর্ক চালালে ঝুঁকি তেমন না কমলেও শেখা দেরি হয়।"],"correctOption":2,"explanationEn":"A repetitive announcement schedule may make moves easy to anticipate.","explanationBn":"একই সময়সূচিতে ঘোষণা দিলে পরবর্তী পদক্ষেপ অনুমান করা সহজ হয়।"},{"id":"apply-the-boundary","questionEn":"A competitor anticipates every public product announcement. Which safeguard best prevents misusing this principle here?","questionBn":"এক প্রতিদ্বন্দ্বী প্রতিটি প্রকাশ্য পণ্য ঘোষণার আগেই তা অনুমান করে ফেলেন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Move quickly when the decision is reversible and the risk bounded. Decisions exposing others to permanent harm need stronger review.","Keep operational obligations predictable even when tactics change. People who rely on you need stable deadlines and a way to reach you.","A launch is only one point in the work. Set responsibilities and evidence requirements for delivery, maintenance, and recovery before committing.","Choice structure can clarify trade-offs or quietly constrain them. Disclose who chose the options and which alternatives were dropped."],"optionsBn":["সিদ্ধান্ত ফিরিয়ে নেওয়া গেলে ও ঝুঁকি সীমিত থাকলে দ্রুত এগোন। অন্যদের স্থায়ী ক্ষতির ঝুঁকি থাকলে কঠোর পর্যালোচনা দরকার।","কৌশল বদলালেও কাজের দায়বদ্ধতা স্থির রাখুন। নির্ভরশীল মানুষের স্থির সময়সীমা ও যোগাযোগের পথ দরকার।","উদ্বোধন কাজের একটি মাত্র ধাপ। প্রতিশ্রুতির আগে সরবরাহ, রক্ষণাবেক্ষণ ও পুনরুদ্ধারের দায়িত্ব এবং প্রমাণের শর্ত ঠিক করুন।","বিকল্প সাজানো সুবিধা-অসুবিধা স্পষ্ট করতে বা গোপনে সীমিত করতে পারে। কে বিকল্প বেছেছেন এবং কোনগুলো বাদ পড়েছে জানান।"],"correctOption":1,"explanationEn":"Keep operational obligations predictable even when tactics change. People who rely on you need stable deadlines and a way to reach you.","explanationBn":"কৌশল বদলালেও কাজের দায়বদ্ধতা স্থির রাখুন। নির্ভরশীল মানুষের স্থির সময়সীমা ও যোগাযোগের পথ দরকার।"}]'::jsonb),
  ('do-not-build-fortress-to-protect-yourself', 'ff51d63fac04e380ea3fefce7ddcc9b3',
    '[{"id":"identify-the-risk","questionEn":"A remote team has stopped hearing about problems in adjacent teams. Which risk does this lesson most directly address?","questionBn":"দূর থেকে কাজ করা একটি দল পাশের দলগুলোর সমস্যা আর জানতে পারছে না। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Old habits can make colleagues keep treating a new manager as an individual contributor.","Isolation cuts off early warnings and leaves the team responding late.","A meeting without a clear process can allow status to determine whose concerns are heard.","Chasing a closed decision can consume the time available for an open opportunity."],"optionsBn":["পুরোনো অভ্যাসে সহকর্মীরা নতুন ব্যবস্থাপককেও স্বতন্ত্র কর্মী হিসেবে দেখতে পারেন।","বিচ্ছিন্নতায় আগাম সতর্কতা পৌঁছায় না, ফলে দল দেরিতে সাড়া দেয়।","স্পষ্ট পদ্ধতি না থাকলে কার কথা শোনা হবে তা সভায় পদমর্যাদা নির্ধারণ করতে পারে।","বন্ধ সিদ্ধান্তের পেছনে ছুটলে খোলা সুযোগের জন্য সময় ফুরিয়ে যেতে পারে।"],"correctOption":1,"explanationEn":"Isolation cuts off early warnings and leaves the team responding late.","explanationBn":"বিচ্ছিন্নতায় আগাম সতর্কতা পৌঁছায় না, ফলে দল দেরিতে সাড়া দেয়।"},{"id":"apply-the-boundary","questionEn":"A remote team has stopped hearing about problems in adjacent teams. Which safeguard best prevents misusing this principle here?","questionBn":"দূর থেকে কাজ করা একটি দল পাশের দলগুলোর সমস্যা আর জানতে পারছে না। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Stop investing attention after the answer is settled, but keep lessons that improve the next attempt. Persistent problems still need a responsible escalation path.","Calculate the cost across the whole relationship. Check exclusivity, future dependence, and data access alongside the headline price.","More contacts help only when useful information can travel both ways. Give partner teams a clear path for reporting problems.","A predecessor''s methods may fit a different set of constraints. Keep the parts that still work and explain the evidence for changing the rest."],"optionsBn":["সিদ্ধান্ত চূড়ান্ত হলে সময় ব্যয় থামান, তবে পরের চেষ্টা উন্নত করে এমন শিক্ষা রাখুন। চলমান সমস্যার জন্য দায়িত্বপূর্ণভাবে বিষয় তোলার পথ দরকার।","পুরো সম্পর্কের ব্যয় হিসাব করুন। ঘোষিত দামের পাশাপাশি একচেটিয়া শর্ত, ভবিষ্যৎ নির্ভরতা ও তথ্যের প্রবেশাধিকার যাচাই করুন।","উপকারী তথ্য দুই দিকেই চললে যোগাযোগ বাড়ানোর লাভ আছে। অন্য দলকে সমস্যা জানানোর স্পষ্ট পথ দিন।","পূর্বসূরির পদ্ধতি ভিন্ন সীমাবদ্ধতার সঙ্গে মানানসই হতে পারে। যা এখনো চলে তা রাখুন এবং বাকিটা বদলের প্রমাণ ব্যাখ্যা করুন।"],"correctOption":2,"explanationEn":"More contacts help only when useful information can travel both ways. Give partner teams a clear path for reporting problems.","explanationBn":"উপকারী তথ্য দুই দিকেই চললে যোগাযোগ বাড়ানোর লাভ আছে। অন্য দলকে সমস্যা জানানোর স্পষ্ট পথ দিন।"}]'::jsonb),
  ('know-who-youre-dealing-with', '0540809e24e3ce95841f09b7d8885785',
    '[{"id":"identify-the-risk","questionEn":"A joke that works with close peers may land badly with a new client. Which risk does this lesson most directly address?","questionBn":"ঘনিষ্ঠ সহকর্মীদের সঙ্গে মানানসই একটি রসিকতা নতুন গ্রাহকের কাছে অস্বস্তিকর হতে পারে। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Familiar humor may not fit the norms or expectations of a new audience.","Personal relationships can bias judgments about who will perform well.","A request that ignores the other team''s workload gives it little reason to commit.","An early promise of exclusive support can undermine independent evaluation."],"optionsBn":["পরিচিত রসিকতা নতুন শ্রোতার রীতি বা প্রত্যাশার সঙ্গে নাও মিলতে পারে।","ব্যক্তিগত সম্পর্ক কে ভালো কাজ করবেন সেই বিচারে পক্ষপাত আনতে পারে।","অন্য দলের কাজের চাপ উপেক্ষা করলে অনুরোধে সম্মত হওয়ার কারণ কম থাকে।","আগেই একচেটিয়া সমর্থনের প্রতিশ্রুতি দিলে স্বাধীন মূল্যায়ন দুর্বল হয়।"],"correctOption":0,"explanationEn":"Familiar humor may not fit the norms or expectations of a new audience.","explanationBn":"পরিচিত রসিকতা নতুন শ্রোতার রীতি বা প্রত্যাশার সঙ্গে নাও মিলতে পারে।"},{"id":"apply-the-boundary","questionEn":"A joke that works with close peers may land badly with a new client. Which safeguard best prevents misusing this principle here?","questionBn":"ঘনিষ্ঠ সহকর্মীদের সঙ্গে মানানসই একটি রসিকতা নতুন গ্রাহকের কাছে অস্বস্তিকর হতে পারে। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Preserve independent judgment while meeting commitments already made. Tell people when and how a decision will actually be taken.","Basic questions test jargon and hidden assumptions. They are most useful when you can also check the answers against independent evidence.","Accept only a reversible compromise whose review date is real. A vague promise to revisit can turn a temporary concession into a permanent one.","Read the circumstances and the person''s expectations before using humor or criticism. Avoid treating title, age, or background as a substitute for observation."],"optionsBn":["আগে দেওয়া প্রতিশ্রুতি রেখে স্বাধীন বিচার বজায় রাখুন। সিদ্ধান্ত কখন ও কীভাবে হবে তা সংশ্লিষ্টদের জানান।","সহজ প্রশ্ন দুর্বোধ্য পরিভাষা ও গোপন অনুমান যাচাই করে। উত্তর স্বাধীন প্রমাণের সঙ্গে মিলিয়ে দেখতে পারলে এগুলো আরও কার্যকর।","যে সাময়িক সমঝোতা ফিরিয়ে নেওয়া যায় এবং যার পর্যালোচনার তারিখ ঠিক আছে সেটিই নিন। অস্পষ্ট আশ্বাসে সাময়িক ছাড় স্থায়ী হতে পারে।","রসিকতা বা সমালোচনার আগে পরিস্থিতি ও ব্যক্তির প্রত্যাশা বুঝুন। পদ, বয়স বা পরিচয়কে পর্যবেক্ষণের বিকল্প ভাববেন না।"],"correctOption":3,"explanationEn":"Read the circumstances and the person''s expectations before using humor or criticism. Avoid treating title, age, or background as a substitute for observation.","explanationBn":"রসিকতা বা সমালোচনার আগে পরিস্থিতি ও ব্যক্তির প্রত্যাশা বুঝুন। পদ, বয়স বা পরিচয়কে পর্যবেক্ষণের বিকল্প ভাববেন না।"}]'::jsonb),
  ('do-not-commit-to-anyone', '0ddbed65f4c6976e809a47cb25b26a3a',
    '[{"id":"identify-the-risk","questionEn":"Two internal groups ask for exclusive support before a proposal is evaluated. Which risk does this lesson most directly address?","questionBn":"প্রস্তাব মূল্যায়নের আগেই দুটি অভ্যন্তরীণ দল একচেটিয়া সমর্থন চায়। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Spreading a small budget across many problems may leave the main bottleneck untouched.","Continuing to debate a reversible trial can delay learning without reducing much risk.","A successful launch can still leave users stranded if support and recovery have no owners.","An early promise of exclusive support can undermine independent evaluation."],"optionsBn":["অল্প বাজেট অনেক সমস্যায় ভাগ করলে মূল বাধা থেকেই যেতে পারে।","ফিরিয়ে নেওয়া যায় এমন পরীক্ষা নিয়ে তর্ক চালালে ঝুঁকি তেমন না কমলেও শেখা দেরি হয়।","উদ্বোধন সফল হলেও সহায়তা ও পুনরুদ্ধারের দায়িত্ব কারও না থাকলে ব্যবহারকারীরা সমস্যায় পড়তে পারেন।","আগেই একচেটিয়া সমর্থনের প্রতিশ্রুতি দিলে স্বাধীন মূল্যায়ন দুর্বল হয়।"],"correctOption":3,"explanationEn":"An early promise of exclusive support can undermine independent evaluation.","explanationBn":"আগেই একচেটিয়া সমর্থনের প্রতিশ্রুতি দিলে স্বাধীন মূল্যায়ন দুর্বল হয়।"},{"id":"apply-the-boundary","questionEn":"Two internal groups ask for exclusive support before a proposal is evaluated. Which safeguard best prevents misusing this principle here?","questionBn":"প্রস্তাব মূল্যায়নের আগেই দুটি অভ্যন্তরীণ দল একচেটিয়া সমর্থন চায়। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Preserve independent judgment while meeting commitments already made. Tell people when and how a decision will actually be taken.","A launch is only one point in the work. Set responsibilities and evidence requirements for delivery, maintenance, and recovery before committing.","Choice structure can clarify trade-offs or quietly constrain them. Disclose who chose the options and which alternatives were dropped.","Agitation can reveal how a discussion is being steered, but it also lowers judgment. Slow the exchange and distinguish evidence from provocation."],"optionsBn":["আগে দেওয়া প্রতিশ্রুতি রেখে স্বাধীন বিচার বজায় রাখুন। সিদ্ধান্ত কখন ও কীভাবে হবে তা সংশ্লিষ্টদের জানান।","উদ্বোধন কাজের একটি মাত্র ধাপ। প্রতিশ্রুতির আগে সরবরাহ, রক্ষণাবেক্ষণ ও পুনরুদ্ধারের দায়িত্ব এবং প্রমাণের শর্ত ঠিক করুন।","বিকল্প সাজানো সুবিধা-অসুবিধা স্পষ্ট করতে বা গোপনে সীমিত করতে পারে। কে বিকল্প বেছেছেন এবং কোনগুলো বাদ পড়েছে জানান।","উত্তেজনা আলোচনা কীভাবে চালিত হচ্ছে তা দেখায়, কিন্তু বিচার দুর্বলও করে। গতি কমিয়ে উসকানি থেকে প্রমাণ আলাদা করুন।"],"correctOption":0,"explanationEn":"Preserve independent judgment while meeting commitments already made. Tell people when and how a decision will actually be taken.","explanationBn":"আগে দেওয়া প্রতিশ্রুতি রেখে স্বাধীন বিচার বজায় রাখুন। সিদ্ধান্ত কখন ও কীভাবে হবে তা সংশ্লিষ্টদের জানান।"}]'::jsonb),
  ('play-a-sucker-to-catch-a-sucker', '9dcda9e88f88d48a49821a1dc785135a',
    '[{"id":"identify-the-risk","questionEn":"A supplier speaks in jargon and assumes you will accept its estimate. Which risk does this lesson most directly address?","questionBn":"এক সরবরাহকারী দুর্বোধ্য পরিভাষা ব্যবহার করে ধরে নিয়েছেন যে আপনি তাঁর হিসাব মেনে নেবেন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Hiding the preparation can erase collaborators'' contributions and make results hard to reproduce.","An appealing promise can hide uncertainty about cost, time, and feasibility.","Jargon can obscure assumptions that determine the estimate.","Important trends can be missed when the evidence is hard to scan or compare."],"optionsBn":["প্রস্তুতি লুকালে সহকর্মীদের অবদান আড়াল হয় ও ফল পুনরায় তৈরি করা কঠিন হয়।","আকর্ষণীয় প্রতিশ্রুতি খরচ, সময় ও বাস্তবসম্ভাব্যতার অনিশ্চয়তা আড়াল করতে পারে।","দুর্বোধ্য পরিভাষা হিসাবের মূল অনুমানগুলো ঢেকে রাখতে পারে।","প্রমাণ দ্রুত পড়া বা তুলনা কঠিন হলে গুরুত্বপূর্ণ ধারা চোখ এড়াতে পারে।"],"correctOption":2,"explanationEn":"Jargon can obscure assumptions that determine the estimate.","explanationBn":"দুর্বোধ্য পরিভাষা হিসাবের মূল অনুমানগুলো ঢেকে রাখতে পারে।"},{"id":"apply-the-boundary","questionEn":"A supplier speaks in jargon and assumes you will accept its estimate. Which safeguard best prevents misusing this principle here?","questionBn":"এক সরবরাহকারী দুর্বোধ্য পরিভাষা ব্যবহার করে ধরে নিয়েছেন যে আপনি তাঁর হিসাব মেনে নেবেন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["A memorable visual should make the relevant evidence easier to inspect. Label scale, missing data, and uncertainty when they affect interpretation.","Basic questions test jargon and hidden assumptions. They are most useful when you can also check the answers against independent evidence.","Accurate reflection can defuse misunderstanding. Imitation used to ridicule the other party often worsens it.","Brevity works when the listener can act on what you said. Include dependencies or uncertainty if leaving them out would cause a bad decision."],"optionsBn":["স্মরণীয় দৃশ্য প্রাসঙ্গিক প্রমাণ যাচাই সহজ করবে। ব্যাখ্যায় প্রভাব ফেললে স্কেল, অনুপস্থিত তথ্য ও অনিশ্চয়তা চিহ্নিত করুন।","সহজ প্রশ্ন দুর্বোধ্য পরিভাষা ও গোপন অনুমান যাচাই করে। উত্তর স্বাধীন প্রমাণের সঙ্গে মিলিয়ে দেখতে পারলে এগুলো আরও কার্যকর।","নির্ভুলভাবে বক্তব্য ফিরিয়ে বললে ভুল বোঝাবুঝি কমে। বিদ্রূপের জন্য অনুকরণ করলে তা প্রায়ই বাড়ে।","শ্রোতা আপনার কথা থেকে কাজ করতে পারলেই সংক্ষিপ্ততা কার্যকর। বাদ দিলে ভুল সিদ্ধান্ত হতে পারে এমন নির্ভরতা বা অনিশ্চয়তা জানান।"],"correctOption":1,"explanationEn":"Basic questions test jargon and hidden assumptions. They are most useful when you can also check the answers against independent evidence.","explanationBn":"সহজ প্রশ্ন দুর্বোধ্য পরিভাষা ও গোপন অনুমান যাচাই করে। উত্তর স্বাধীন প্রমাণের সঙ্গে মিলিয়ে দেখতে পারলে এগুলো আরও কার্যকর।"}]'::jsonb),
  ('use-surrender-tactic-transform-weakness-into-power', '3af8dd9ec498c9da670d963f9cc6fee8',
    '[{"id":"identify-the-risk","questionEn":"A small team cannot win an immediate dispute over meeting space. Which risk does this lesson most directly address?","questionBn":"সভাকক্ষ নিয়ে তাৎক্ষণিক বিরোধে ছোট একটি দলের জেতার সুযোগ নেই। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Reviewers handling an urgent incident may have too little attention for a major proposal.","Confrontation at a disadvantage can consume resources without improving your position.","Ignoring unfamiliar communication norms may create friction before substantive issues get a hearing.","Changing several tools at once makes disruption harder to diagnose and reverse."],"optionsBn":["জরুরি ঘটনা সামলানো পর্যালোচকেরা বড় প্রস্তাবে যথেষ্ট মনোযোগ দিতে নাও পারেন।","দুর্বল অবস্থায় সরাসরি বিরোধে সম্পদ ক্ষয় হলেও অবস্থার উন্নতি নাও হতে পারে।","অপরিচিত যোগাযোগরীতি উপেক্ষা করলে মূল বিষয় শোনার আগেই বিরোধ তৈরি হতে পারে।","একসঙ্গে কয়েকটি সরঞ্জাম বদলালে বিঘ্নের কারণ ধরা ও পূর্বাবস্থায় ফেরা কঠিন হয়।"],"correctOption":1,"explanationEn":"Confrontation at a disadvantage can consume resources without improving your position.","explanationBn":"দুর্বল অবস্থায় সরাসরি বিরোধে সম্পদ ক্ষয় হলেও অবস্থার উন্নতি নাও হতে পারে।"},{"id":"apply-the-boundary","questionEn":"A small team cannot win an immediate dispute over meeting space. Which safeguard best prevents misusing this principle here?","questionBn":"সভাকক্ষ নিয়ে তাৎক্ষণিক বিরোধে ছোট একটি দলের জেতার সুযোগ নেই। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Phasing helps people learn what works before a full change. Set clear measures for moving ahead, pausing, or rolling back.","Flexibility is about changing methods while honoring durable commitments. Measure alternatives against the same outcome so adaptation remains accountable.","Accept only a reversible compromise whose review date is real. A vague promise to revisit can turn a temporary concession into a permanent one.","Concentrate effort where there is evidence of a bottleneck. Keep essential maintenance funded even when a pilot has a single focus."],"optionsBn":["ধাপে কাজ করলে পুরো পরিবর্তনের আগে কী কার্যকর বোঝা যায়। এগোনো, থামা বা পূর্বাবস্থায় ফেরার স্পষ্ট মাপকাঠি দিন।","নমনীয়তা হলো দীর্ঘমেয়াদি প্রতিশ্রুতি রেখে পদ্ধতি বদলানো। একই ফলের মাপকাঠি দিয়ে বিকল্প বিচার করলে অভিযোজন জবাবদিহির আওতায় থাকে।","যে সাময়িক সমঝোতা ফিরিয়ে নেওয়া যায় এবং যার পর্যালোচনার তারিখ ঠিক আছে সেটিই নিন। অস্পষ্ট আশ্বাসে সাময়িক ছাড় স্থায়ী হতে পারে।","বাধার প্রমাণ যে জায়গায় আছে সেখানে প্রচেষ্টা দিন। পরীক্ষার লক্ষ্য একটি হলেও প্রয়োজনীয় রক্ষণাবেক্ষণের অর্থ রাখুন।"],"correctOption":2,"explanationEn":"Accept only a reversible compromise whose review date is real. A vague promise to revisit can turn a temporary concession into a permanent one.","explanationBn":"যে সাময়িক সমঝোতা ফিরিয়ে নেওয়া যায় এবং যার পর্যালোচনার তারিখ ঠিক আছে সেটিই নিন। অস্পষ্ট আশ্বাসে সাময়িক ছাড় স্থায়ী হতে পারে।"}]'::jsonb),
  ('concentrate-your-forces', '8b9842ffe7cb136ad4f279943dc15db0',
    '[{"id":"identify-the-risk","questionEn":"A pilot has funding for one meaningful improvement. Which risk does this lesson most directly address?","questionBn":"পরীক্ষামূলক উদ্যোগে একটি অর্থপূর্ণ উন্নতির জন্য অর্থ আছে। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Spreading a small budget across many problems may leave the main bottleneck untouched.","Continuing to debate a reversible trial can delay learning without reducing much risk.","A successful launch can still leave users stranded if support and recovery have no owners.","Unequal descriptions can steer people toward one schedule before they compare trade-offs."],"optionsBn":["অল্প বাজেট অনেক সমস্যায় ভাগ করলে মূল বাধা থেকেই যেতে পারে।","ফিরিয়ে নেওয়া যায় এমন পরীক্ষা নিয়ে তর্ক চালালে ঝুঁকি তেমন না কমলেও শেখা দেরি হয়।","উদ্বোধন সফল হলেও সহায়তা ও পুনরুদ্ধারের দায়িত্ব কারও না থাকলে ব্যবহারকারীরা সমস্যায় পড়তে পারেন।","বিকল্পের অসম বর্ণনা সুবিধা-অসুবিধা তুলনার আগেই মানুষকে এক সময়সূচির দিকে ঠেলে দিতে পারে।"],"correctOption":0,"explanationEn":"Spreading a small budget across many problems may leave the main bottleneck untouched.","explanationBn":"অল্প বাজেট অনেক সমস্যায় ভাগ করলে মূল বাধা থেকেই যেতে পারে।"},{"id":"apply-the-boundary","questionEn":"A pilot has funding for one meaningful improvement. Which safeguard best prevents misusing this principle here?","questionBn":"পরীক্ষামূলক উদ্যোগে একটি অর্থপূর্ণ উন্নতির জন্য অর্থ আছে। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Choice structure can clarify trade-offs or quietly constrain them. Disclose who chose the options and which alternatives were dropped.","Agitation can reveal how a discussion is being steered, but it also lowers judgment. Slow the exchange and distinguish evidence from provocation.","Test whether a single role is an actual bottleneck before redistributing authority. Improve the process without targeting the person who held the role.","Concentrate effort where there is evidence of a bottleneck. Keep essential maintenance funded even when a pilot has a single focus."],"optionsBn":["বিকল্প সাজানো সুবিধা-অসুবিধা স্পষ্ট করতে বা গোপনে সীমিত করতে পারে। কে বিকল্প বেছেছেন এবং কোনগুলো বাদ পড়েছে জানান।","উত্তেজনা আলোচনা কীভাবে চালিত হচ্ছে তা দেখায়, কিন্তু বিচার দুর্বলও করে। গতি কমিয়ে উসকানি থেকে প্রমাণ আলাদা করুন।","কর্তৃত্ব ভাগ করার আগে একক ভূমিকাটি সত্যিই বাধা কি না যাচাই করুন। পদধারী ব্যক্তিকে লক্ষ্য না করে প্রক্রিয়া উন্নত করুন।","বাধার প্রমাণ যে জায়গায় আছে সেখানে প্রচেষ্টা দিন। পরীক্ষার লক্ষ্য একটি হলেও প্রয়োজনীয় রক্ষণাবেক্ষণের অর্থ রাখুন।"],"correctOption":3,"explanationEn":"Concentrate effort where there is evidence of a bottleneck. Keep essential maintenance funded even when a pilot has a single focus.","explanationBn":"বাধার প্রমাণ যে জায়গায় আছে সেখানে প্রচেষ্টা দিন। পরীক্ষার লক্ষ্য একটি হলেও প্রয়োজনীয় রক্ষণাবেক্ষণের অর্থ রাখুন।"}]'::jsonb),
  ('play-the-perfect-courtier', 'e71b253c104cf7ee3a5a734e2f807bb4',
    '[{"id":"identify-the-risk","questionEn":"You need to raise an executive decision that hurt another team. Which risk does this lesson most directly address?","questionBn":"ঊর্ধ্বতনের একটি সিদ্ধান্ত অন্য দলের ক্ষতি করেছে এবং বিষয়টি তুলতে হবে। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Discouraging questions can make loyalty replace independent judgment.","A process may meet its formal goal while making someone''s contribution harder to see.","A schedule that ignores caregiving constraints can generate resistance even when people support the goal.","Public embarrassment can make people defend a decision before hearing the evidence."],"optionsBn":["প্রশ্ন নিরুৎসাহিত করলে স্বাধীন বিচারের জায়গায় আনুগত্য চলে আসতে পারে।","প্রক্রিয়া আনুষ্ঠানিক লক্ষ্য পূরণ করলেও কারও অবদান দেখা কঠিন করে দিতে পারে।","পরিচর্যার সীমা উপেক্ষা করা সময়সূচি লক্ষ্যে সমর্থন থাকলেও বিরোধ ডেকে আনতে পারে।","প্রকাশ্য বিব্রতকর অবস্থায় মানুষ প্রমাণ শোনার আগেই সিদ্ধান্তের সপক্ষে দাঁড়াতে পারে।"],"correctOption":3,"explanationEn":"Public embarrassment can make people defend a decision before hearing the evidence.","explanationBn":"প্রকাশ্য বিব্রতকর অবস্থায় মানুষ প্রমাণ শোনার আগেই সিদ্ধান্তের সপক্ষে দাঁড়াতে পারে।"},{"id":"apply-the-boundary","questionEn":"You need to raise an executive decision that hurt another team. Which safeguard best prevents misusing this principle here?","questionBn":"ঊর্ধ্বতনের একটি সিদ্ধান্ত অন্য দলের ক্ষতি করেছে এবং বিষয়টি তুলতে হবে। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Tact improves the chance that evidence is heard. Use formal reporting in situations that require accountability or independent review.","Concern is information about a real implementation constraint. Demonstrate that you heard it by showing what changed and why.","Coordination is a real contribution. Distinguish it from research, design, and delivery so the team can recognize each person''s work.","Define the comparison before you see the numbers. Include error rate and accessibility alongside speed so the faster template does not disguise worse service."],"optionsBn":["কৌশলী উপস্থাপনা প্রমাণ শোনার সম্ভাবনা বাড়ায়। জবাবদিহি বা স্বাধীন পর্যালোচনা দরকার হলে আনুষ্ঠানিকভাবে জানান।","উদ্বেগ বাস্তবায়নের প্রকৃত সীমার তথ্য দেয়। কী বদলেছে ও কেন তা দেখিয়ে বোঝান যে আপনি কথা শুনেছেন।","সমন্বয়ও বাস্তব অবদান। গবেষণা, নকশা ও সরবরাহ থেকে তা আলাদা করে প্রতিটি মানুষের কাজ চিহ্নিত করুন।","ফল দেখার আগে তুলনার মানদণ্ড ঠিক করুন। গতির পাশাপাশি ভুলের হার ও প্রবেশগম্যতা ধরুন যাতে দ্রুততর টেমপ্লেট খারাপ সেবা ঢেকে না দেয়।"],"correctOption":0,"explanationEn":"Tact improves the chance that evidence is heard. Use formal reporting in situations that require accountability or independent review.","explanationBn":"কৌশলী উপস্থাপনা প্রমাণ শোনার সম্ভাবনা বাড়ায়। জবাবদিহি বা স্বাধীন পর্যালোচনা দরকার হলে আনুষ্ঠানিকভাবে জানান।"}]'::jsonb),
  ('re-create-yourself', 'df8c3adfe6861df36121f47ac079eb3f',
    '[{"id":"identify-the-risk","questionEn":"You move from individual contributor to team manager. Which risk does this lesson most directly address?","questionBn":"আপনি স্বতন্ত্র কর্মীর ভূমিকা থেকে দল পরিচালনায় এসেছেন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["A meeting without a clear process can allow status to determine whose concerns are heard.","Chasing a closed decision can consume the time available for an open opportunity.","Old habits can make colleagues keep treating a new manager as an individual contributor.","A zero price can conceal obligations that have a real cost later."],"optionsBn":["স্পষ্ট পদ্ধতি না থাকলে কার কথা শোনা হবে তা সভায় পদমর্যাদা নির্ধারণ করতে পারে।","বন্ধ সিদ্ধান্তের পেছনে ছুটলে খোলা সুযোগের জন্য সময় ফুরিয়ে যেতে পারে।","পুরোনো অভ্যাসে সহকর্মীরা নতুন ব্যবস্থাপককেও স্বতন্ত্র কর্মী হিসেবে দেখতে পারেন।","শূন্য দাম ভবিষ্যতের বাস্তব ব্যয়যুক্ত দায়বদ্ধতা আড়াল করতে পারে।"],"correctOption":2,"explanationEn":"Old habits can make colleagues keep treating a new manager as an individual contributor.","explanationBn":"পুরোনো অভ্যাসে সহকর্মীরা নতুন ব্যবস্থাপককেও স্বতন্ত্র কর্মী হিসেবে দেখতে পারেন।"},{"id":"apply-the-boundary","questionEn":"You move from individual contributor to team manager. Which safeguard best prevents misusing this principle here?","questionBn":"আপনি স্বতন্ত্র কর্মীর ভূমিকা থেকে দল পরিচালনায় এসেছেন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Calculate the cost across the whole relationship. Check exclusivity, future dependence, and data access alongside the headline price.","A new role becomes credible through repeated behavior. Communicate which responsibilities changed and who now owns your former work.","A predecessor''s methods may fit a different set of constraints. Keep the parts that still work and explain the evidence for changing the rest.","Define the stopping rule before success changes your incentives. A new opportunity needs a fresh decision with its own costs and risks."],"optionsBn":["পুরো সম্পর্কের ব্যয় হিসাব করুন। ঘোষিত দামের পাশাপাশি একচেটিয়া শর্ত, ভবিষ্যৎ নির্ভরতা ও তথ্যের প্রবেশাধিকার যাচাই করুন।","পুনরাবৃত্ত আচরণে নতুন ভূমিকা বিশ্বাসযোগ্য হয়। কোন দায়িত্ব বদলেছে এবং আগের কাজ এখন কার তা জানান।","পূর্বসূরির পদ্ধতি ভিন্ন সীমাবদ্ধতার সঙ্গে মানানসই হতে পারে। যা এখনো চলে তা রাখুন এবং বাকিটা বদলের প্রমাণ ব্যাখ্যা করুন।","সাফল্য আপনার প্রণোদনা বদলানোর আগে থামার নিয়ম ঠিক করুন। নতুন সুযোগের ব্যয় ও ঝুঁকি ধরে নতুন সিদ্ধান্ত নিন।"],"correctOption":1,"explanationEn":"A new role becomes credible through repeated behavior. Communicate which responsibilities changed and who now owns your former work.","explanationBn":"পুনরাবৃত্ত আচরণে নতুন ভূমিকা বিশ্বাসযোগ্য হয়। কোন দায়িত্ব বদলেছে এবং আগের কাজ এখন কার তা জানান।"}]'::jsonb),
  ('keep-your-hands-clean', '551ad94ad75f7ef15459d5cd2920e64d',
    '[{"id":"identify-the-risk","questionEn":"A manager asks you to send an undocumented exception to policy. Which risk does this lesson most directly address?","questionBn":"একজন ব্যবস্থাপক নীতির একটি অলিখিত ব্যতিক্রম কার্যকর করতে বলেছেন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["An image of effortless success can hide lessons others need to repeat the result.","An undocumented exception makes accountability and consistent treatment difficult.","An unsupported public claim can undermine trust in verified work.","Unlimited availability can exhaust the mentor and make access less dependable."],"optionsBn":["অনায়াস সাফল্যের ছবি ফল পুনরায় অর্জনের জন্য দরকারি শিক্ষা আড়াল করতে পারে।","অলিখিত ব্যতিক্রম জবাবদিহি ও সমান আচরণ কঠিন করে।","প্রমাণহীন প্রকাশ্য দাবি যাচাইকৃত কাজের ওপরও আস্থা কমাতে পারে।","সীমাহীন প্রাপ্যতা পরামর্শদাতাকে ক্লান্ত করে এবং সহায়তা পাওয়া অনিশ্চিত করে।"],"correctOption":1,"explanationEn":"An undocumented exception makes accountability and consistent treatment difficult.","explanationBn":"অলিখিত ব্যতিক্রম জবাবদিহি ও সমান আচরণ কঠিন করে।"},{"id":"apply-the-boundary","questionEn":"A manager asks you to send an undocumented exception to policy. Which safeguard best prevents misusing this principle here?","questionBn":"একজন ব্যবস্থাপক নীতির একটি অলিখিত ব্যতিক্রম কার্যকর করতে বলেছেন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Predictable availability makes a boundary workable for others. Absence that interrupts promised support erodes the respect you wanted to preserve.","Belonging can motivate cooperation, but demands for uncritical loyalty undermine judgment. Look for transparent claims, safe disagreement, and accountability.","A reliable record includes your own part in a decision. Delegating a task does not transfer responsibility for approving it.","Move quickly when the decision is reversible and the risk bounded. Decisions exposing others to permanent harm need stronger review."],"optionsBn":["কখন পাওয়া যাবে জানা থাকলে অন্যরা সীমা মেনে কাজ করতে পারেন। প্রতিশ্রুত সহায়তা বন্ধ করা অনুপস্থিতি সম্মান ক্ষয় করে।","অন্তর্ভুক্তির অনুভূতি সহযোগিতা বাড়ায়, কিন্তু প্রশ্নহীন আনুগত্য বিচারশক্তি ক্ষয় করে। স্বচ্ছ দাবি, নিরাপদ ভিন্নমত ও জবাবদিহি দেখুন।","নির্ভরযোগ্য নথিতে সিদ্ধান্তে আপনার ভূমিকাও থাকে। কাজ ভাগ করলেই অনুমোদনের দায় অন্যের কাছে যায় না।","সিদ্ধান্ত ফিরিয়ে নেওয়া গেলে ও ঝুঁকি সীমিত থাকলে দ্রুত এগোন। অন্যদের স্থায়ী ক্ষতির ঝুঁকি থাকলে কঠোর পর্যালোচনা দরকার।"],"correctOption":2,"explanationEn":"A reliable record includes your own part in a decision. Delegating a task does not transfer responsibility for approving it.","explanationBn":"নির্ভরযোগ্য নথিতে সিদ্ধান্তে আপনার ভূমিকাও থাকে। কাজ ভাগ করলেই অনুমোদনের দায় অন্যের কাছে যায় না।"}]'::jsonb),
  ('play-on-peoples-need-to-believe', 'a28a84df507c18c536e75f2ea4856b18',
    '[{"id":"identify-the-risk","questionEn":"A charismatic group leader discourages anyone from questioning promises. Which risk does this lesson most directly address?","questionBn":"এক আকর্ষণীয় দলনেতা তাঁর প্রতিশ্রুতি নিয়ে প্রশ্ন করতে সবাইকে নিরুৎসাহিত করেন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Discouraging questions can make loyalty replace independent judgment.","A process may meet its formal goal while making someone''s contribution harder to see.","A schedule that ignores caregiving constraints can generate resistance even when people support the goal.","Taking sole credit erodes contributors'' trust and willingness to help again."],"optionsBn":["প্রশ্ন নিরুৎসাহিত করলে স্বাধীন বিচারের জায়গায় আনুগত্য চলে আসতে পারে।","প্রক্রিয়া আনুষ্ঠানিক লক্ষ্য পূরণ করলেও কারও অবদান দেখা কঠিন করে দিতে পারে।","পরিচর্যার সীমা উপেক্ষা করা সময়সূচি লক্ষ্যে সমর্থন থাকলেও বিরোধ ডেকে আনতে পারে।","একাই কৃতিত্ব নিলে সহযোগীদের আস্থা ও আবার সাহায্য করার আগ্রহ কমে।"],"correctOption":0,"explanationEn":"Discouraging questions can make loyalty replace independent judgment.","explanationBn":"প্রশ্ন নিরুৎসাহিত করলে স্বাধীন বিচারের জায়গায় আনুগত্য চলে আসতে পারে।"},{"id":"apply-the-boundary","questionEn":"A charismatic group leader discourages anyone from questioning promises. Which safeguard best prevents misusing this principle here?","questionBn":"এক আকর্ষণীয় দলনেতা তাঁর প্রতিশ্রুতি নিয়ে প্রশ্ন করতে সবাইকে নিরুৎসাহিত করেন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Coordination is a real contribution. Distinguish it from research, design, and delivery so the team can recognize each person''s work.","Define the comparison before you see the numbers. Include error rate and accessibility alongside speed so the faster template does not disguise worse service.","An honest disclosure or generous gesture is evidence of that act alone. Check the broader deal, including price, conditions, and obligations.","Belonging can motivate cooperation, but demands for uncritical loyalty undermine judgment. Look for transparent claims, safe disagreement, and accountability."],"optionsBn":["সমন্বয়ও বাস্তব অবদান। গবেষণা, নকশা ও সরবরাহ থেকে তা আলাদা করে প্রতিটি মানুষের কাজ চিহ্নিত করুন।","ফল দেখার আগে তুলনার মানদণ্ড ঠিক করুন। গতির পাশাপাশি ভুলের হার ও প্রবেশগম্যতা ধরুন যাতে দ্রুততর টেমপ্লেট খারাপ সেবা ঢেকে না দেয়।","সৎ স্বীকারোক্তি বা উদারতা শুধু সেই কাজের প্রমাণ। দাম, শর্ত ও দায়বদ্ধতাসহ পুরো চুক্তি যাচাই করুন।","অন্তর্ভুক্তির অনুভূতি সহযোগিতা বাড়ায়, কিন্তু প্রশ্নহীন আনুগত্য বিচারশক্তি ক্ষয় করে। স্বচ্ছ দাবি, নিরাপদ ভিন্নমত ও জবাবদিহি দেখুন।"],"correctOption":3,"explanationEn":"Belonging can motivate cooperation, but demands for uncritical loyalty undermine judgment. Look for transparent claims, safe disagreement, and accountability.","explanationBn":"অন্তর্ভুক্তির অনুভূতি সহযোগিতা বাড়ায়, কিন্তু প্রশ্নহীন আনুগত্য বিচারশক্তি ক্ষয় করে। স্বচ্ছ দাবি, নিরাপদ ভিন্নমত ও জবাবদিহি দেখুন।"}]'::jsonb),
  ('enter-action-with-boldness', 'c87a7c6cff8758fa03c7f575e4607085',
    '[{"id":"identify-the-risk","questionEn":"A reversible experiment has been delayed for weeks by indecision. Which risk does this lesson most directly address?","questionBn":"সহজে ফিরিয়ে নেওয়া যায় এমন একটি পরীক্ষা সিদ্ধান্তহীনতায় কয়েক সপ্তাহ দেরি হয়েছে। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["A successful launch can still leave users stranded if support and recovery have no owners.","Unequal descriptions can steer people toward one schedule before they compare trade-offs.","Emotional escalation makes accusations feel more persuasive than verifiable evidence.","Continuing to debate a reversible trial can delay learning without reducing much risk."],"optionsBn":["উদ্বোধন সফল হলেও সহায়তা ও পুনরুদ্ধারের দায়িত্ব কারও না থাকলে ব্যবহারকারীরা সমস্যায় পড়তে পারেন।","বিকল্পের অসম বর্ণনা সুবিধা-অসুবিধা তুলনার আগেই মানুষকে এক সময়সূচির দিকে ঠেলে দিতে পারে।","আবেগ বেড়ে গেলে যাচাইযোগ্য প্রমাণের চেয়ে অভিযোগ বেশি বিশ্বাসযোগ্য মনে হতে পারে।","ফিরিয়ে নেওয়া যায় এমন পরীক্ষা নিয়ে তর্ক চালালে ঝুঁকি তেমন না কমলেও শেখা দেরি হয়।"],"correctOption":3,"explanationEn":"Continuing to debate a reversible trial can delay learning without reducing much risk.","explanationBn":"ফিরিয়ে নেওয়া যায় এমন পরীক্ষা নিয়ে তর্ক চালালে ঝুঁকি তেমন না কমলেও শেখা দেরি হয়।"},{"id":"apply-the-boundary","questionEn":"A reversible experiment has been delayed for weeks by indecision. Which safeguard best prevents misusing this principle here?","questionBn":"সহজে ফিরিয়ে নেওয়া যায় এমন একটি পরীক্ষা সিদ্ধান্তহীনতায় কয়েক সপ্তাহ দেরি হয়েছে। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Move quickly when the decision is reversible and the risk bounded. Decisions exposing others to permanent harm need stronger review.","Agitation can reveal how a discussion is being steered, but it also lowers judgment. Slow the exchange and distinguish evidence from provocation.","Test whether a single role is an actual bottleneck before redistributing authority. Improve the process without targeting the person who held the role.","Distinguish legitimate confidentiality from omissions that affect informed consent. Name when and to whom more can be disclosed."],"optionsBn":["সিদ্ধান্ত ফিরিয়ে নেওয়া গেলে ও ঝুঁকি সীমিত থাকলে দ্রুত এগোন। অন্যদের স্থায়ী ক্ষতির ঝুঁকি থাকলে কঠোর পর্যালোচনা দরকার।","উত্তেজনা আলোচনা কীভাবে চালিত হচ্ছে তা দেখায়, কিন্তু বিচার দুর্বলও করে। গতি কমিয়ে উসকানি থেকে প্রমাণ আলাদা করুন।","কর্তৃত্ব ভাগ করার আগে একক ভূমিকাটি সত্যিই বাধা কি না যাচাই করুন। পদধারী ব্যক্তিকে লক্ষ্য না করে প্রক্রিয়া উন্নত করুন।","বৈধ গোপনীয়তা ও অবহিত সম্মতিতে প্রভাব ফেলা তথ্য গোপনের পার্থক্য বুঝুন। কখন ও কাকে বিস্তারিত বলা যাবে তা জানান।"],"correctOption":0,"explanationEn":"Move quickly when the decision is reversible and the risk bounded. Decisions exposing others to permanent harm need stronger review.","explanationBn":"সিদ্ধান্ত ফিরিয়ে নেওয়া গেলে ও ঝুঁকি সীমিত থাকলে দ্রুত এগোন। অন্যদের স্থায়ী ক্ষতির ঝুঁকি থাকলে কঠোর পর্যালোচনা দরকার।"}]'::jsonb),
  ('plan-all-the-way-to-the-end', 'c6236ef4be33ec0076eaddca1230f905',
    '[{"id":"identify-the-risk","questionEn":"A team plans a migration but has only scheduled the launch. Which risk does this lesson most directly address?","questionBn":"একটি দল সিস্টেম স্থানান্তরের পরিকল্পনায় কেবল চালুর সময় ঠিক করেছে। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Unequal descriptions can steer people toward one schedule before they compare trade-offs.","Emotional escalation makes accusations feel more persuasive than verifiable evidence.","A successful launch can still leave users stranded if support and recovery have no owners.","Concentrating approvals in one role can stall the entire group''s routine work."],"optionsBn":["বিকল্পের অসম বর্ণনা সুবিধা-অসুবিধা তুলনার আগেই মানুষকে এক সময়সূচির দিকে ঠেলে দিতে পারে।","আবেগ বেড়ে গেলে যাচাইযোগ্য প্রমাণের চেয়ে অভিযোগ বেশি বিশ্বাসযোগ্য মনে হতে পারে।","উদ্বোধন সফল হলেও সহায়তা ও পুনরুদ্ধারের দায়িত্ব কারও না থাকলে ব্যবহারকারীরা সমস্যায় পড়তে পারেন।","অনুমোদন একটি পদে কেন্দ্রীভূত করলে পুরো দলের নিয়মিত কাজ থেমে যেতে পারে।"],"correctOption":2,"explanationEn":"A successful launch can still leave users stranded if support and recovery have no owners.","explanationBn":"উদ্বোধন সফল হলেও সহায়তা ও পুনরুদ্ধারের দায়িত্ব কারও না থাকলে ব্যবহারকারীরা সমস্যায় পড়তে পারেন।"},{"id":"apply-the-boundary","questionEn":"A team plans a migration but has only scheduled the launch. Which safeguard best prevents misusing this principle here?","questionBn":"একটি দল সিস্টেম স্থানান্তরের পরিকল্পনায় কেবল চালুর সময় ঠিক করেছে। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Test whether a single role is an actual bottleneck before redistributing authority. Improve the process without targeting the person who held the role.","A launch is only one point in the work. Set responsibilities and evidence requirements for delivery, maintenance, and recovery before committing.","Distinguish legitimate confidentiality from omissions that affect informed consent. Name when and to whom more can be disclosed.","An invitation should have value even if the recipient declines the larger proposal. Avoid hidden obligations that make the first interaction feel deceptive."],"optionsBn":["কর্তৃত্ব ভাগ করার আগে একক ভূমিকাটি সত্যিই বাধা কি না যাচাই করুন। পদধারী ব্যক্তিকে লক্ষ্য না করে প্রক্রিয়া উন্নত করুন।","উদ্বোধন কাজের একটি মাত্র ধাপ। প্রতিশ্রুতির আগে সরবরাহ, রক্ষণাবেক্ষণ ও পুনরুদ্ধারের দায়িত্ব এবং প্রমাণের শর্ত ঠিক করুন।","বৈধ গোপনীয়তা ও অবহিত সম্মতিতে প্রভাব ফেলা তথ্য গোপনের পার্থক্য বুঝুন। কখন ও কাকে বিস্তারিত বলা যাবে তা জানান।","বড় প্রস্তাব প্রত্যাখ্যান করলেও আমন্ত্রণটি প্রাপকের কাজে লাগা উচিত। প্রথম যোগাযোগকে প্রতারণামূলক করে এমন গোপন শর্ত এড়ান।"],"correctOption":1,"explanationEn":"A launch is only one point in the work. Set responsibilities and evidence requirements for delivery, maintenance, and recovery before committing.","explanationBn":"উদ্বোধন কাজের একটি মাত্র ধাপ। প্রতিশ্রুতির আগে সরবরাহ, রক্ষণাবেক্ষণ ও পুনরুদ্ধারের দায়িত্ব এবং প্রমাণের শর্ত ঠিক করুন।"}]'::jsonb),
  ('make-your-accomplishments-seem-effortless', 'a09aed42db80ce4d220fef055af1f2c9',
    '[{"id":"identify-the-risk","questionEn":"Your demonstration is polished because several teammates rehearsed for days. Which risk does this lesson most directly address?","questionBn":"কয়েকজন সহকর্মী কয়েক দিন অনুশীলন করায় আপনার প্রদর্শনী সাবলীল হয়েছে। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["An appealing promise can hide uncertainty about cost, time, and feasibility.","Hiding the preparation can erase collaborators'' contributions and make results hard to reproduce.","Important trends can be missed when the evidence is hard to scan or compare.","Each team may be reacting to a different account of the same deadline changes."],"optionsBn":["আকর্ষণীয় প্রতিশ্রুতি খরচ, সময় ও বাস্তবসম্ভাব্যতার অনিশ্চয়তা আড়াল করতে পারে।","প্রস্তুতি লুকালে সহকর্মীদের অবদান আড়াল হয় ও ফল পুনরায় তৈরি করা কঠিন হয়।","প্রমাণ দ্রুত পড়া বা তুলনা কঠিন হলে গুরুত্বপূর্ণ ধারা চোখ এড়াতে পারে।","একই সময়সীমা পরিবর্তন সম্পর্কে দুই দল ভিন্ন বর্ণনার ভিত্তিতে প্রতিক্রিয়া জানাতে পারে।"],"correctOption":1,"explanationEn":"Hiding the preparation can erase collaborators'' contributions and make results hard to reproduce.","explanationBn":"প্রস্তুতি লুকালে সহকর্মীদের অবদান আড়াল হয় ও ফল পুনরায় তৈরি করা কঠিন হয়।"},{"id":"apply-the-boundary","questionEn":"Your demonstration is polished because several teammates rehearsed for days. Which safeguard best prevents misusing this principle here?","questionBn":"কয়েকজন সহকর্মী কয়েক দিন অনুশীলন করায় আপনার প্রদর্শনী সাবলীল হয়েছে। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Accurate reflection can defuse misunderstanding. Imitation used to ridicule the other party often worsens it.","Brevity works when the listener can act on what you said. Include dependencies or uncertainty if leaving them out would cause a bad decision.","A fluent presentation reduces friction for the audience. Keep enough of the preparation visible that others can reproduce the result.","Visibility is valuable when the audience can verify what changed. Exaggeration may win attention once and make the next announcement less credible."],"optionsBn":["নির্ভুলভাবে বক্তব্য ফিরিয়ে বললে ভুল বোঝাবুঝি কমে। বিদ্রূপের জন্য অনুকরণ করলে তা প্রায়ই বাড়ে।","শ্রোতা আপনার কথা থেকে কাজ করতে পারলেই সংক্ষিপ্ততা কার্যকর। বাদ দিলে ভুল সিদ্ধান্ত হতে পারে এমন নির্ভরতা বা অনিশ্চয়তা জানান।","সাবলীল উপস্থাপনা দর্শকের বোঝা সহজ করে। অন্যরা যেন ফল পুনরায় তৈরি করতে পারেন, সে জন্য যথেষ্ট প্রস্তুতি দৃশ্যমান রাখুন।","দর্শক পরিবর্তন যাচাই করতে পারলে দৃশ্যমানতা মূল্যবান। অতিরঞ্জন একবার নজর কাড়লেও পরের ঘোষণার বিশ্বাসযোগ্যতা কমায়।"],"correctOption":2,"explanationEn":"A fluent presentation reduces friction for the audience. Keep enough of the preparation visible that others can reproduce the result.","explanationBn":"সাবলীল উপস্থাপনা দর্শকের বোঝা সহজ করে। অন্যরা যেন ফল পুনরায় তৈরি করতে পারেন, সে জন্য যথেষ্ট প্রস্তুতি দৃশ্যমান রাখুন।"}]'::jsonb),
  ('control-the-options-get-others-to-play-with-the-cards-you-deal', '18d388804c5d998aa8d61f62ea34552a',
    '[{"id":"identify-the-risk","questionEn":"Residents must choose between plausible service schedules. Which risk does this lesson most directly address?","questionBn":"বাসিন্দাদের কয়েকটি বাস্তবসম্মত সেবার সময়সূচি থেকে বেছে নিতে হবে। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Unequal descriptions can steer people toward one schedule before they compare trade-offs.","Emotional escalation makes accusations feel more persuasive than verifiable evidence.","Concentrating approvals in one role can stall the entire group''s routine work.","Announcing tentative terms can reduce room to negotiate or create premature expectations."],"optionsBn":["বিকল্পের অসম বর্ণনা সুবিধা-অসুবিধা তুলনার আগেই মানুষকে এক সময়সূচির দিকে ঠেলে দিতে পারে।","আবেগ বেড়ে গেলে যাচাইযোগ্য প্রমাণের চেয়ে অভিযোগ বেশি বিশ্বাসযোগ্য মনে হতে পারে।","অনুমোদন একটি পদে কেন্দ্রীভূত করলে পুরো দলের নিয়মিত কাজ থেমে যেতে পারে।","অস্থায়ী শর্ত ঘোষণা করলে আলোচনার সুযোগ কমে বা অকালে প্রত্যাশা তৈরি হয়।"],"correctOption":0,"explanationEn":"Unequal descriptions can steer people toward one schedule before they compare trade-offs.","explanationBn":"বিকল্পের অসম বর্ণনা সুবিধা-অসুবিধা তুলনার আগেই মানুষকে এক সময়সূচির দিকে ঠেলে দিতে পারে।"},{"id":"apply-the-boundary","questionEn":"Residents must choose between plausible service schedules. Which safeguard best prevents misusing this principle here?","questionBn":"বাসিন্দাদের কয়েকটি বাস্তবসম্মত সেবার সময়সূচি থেকে বেছে নিতে হবে। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Distinguish legitimate confidentiality from omissions that affect informed consent. Name when and to whom more can be disclosed.","An invitation should have value even if the recipient declines the larger proposal. Avoid hidden obligations that make the first interaction feel deceptive.","A durable settlement removes the circumstances that recreate the conflict. Retaliation leaves the root cause in place and adds another dispute.","Choice structure can clarify trade-offs or quietly constrain them. Disclose who chose the options and which alternatives were dropped."],"optionsBn":["বৈধ গোপনীয়তা ও অবহিত সম্মতিতে প্রভাব ফেলা তথ্য গোপনের পার্থক্য বুঝুন। কখন ও কাকে বিস্তারিত বলা যাবে তা জানান।","বড় প্রস্তাব প্রত্যাখ্যান করলেও আমন্ত্রণটি প্রাপকের কাজে লাগা উচিত। প্রথম যোগাযোগকে প্রতারণামূলক করে এমন গোপন শর্ত এড়ান।","টেকসই সমাধান সংঘাত আবার তৈরি হওয়ার পরিস্থিতি দূর করে। প্রতিশোধ মূল কারণ রেখে নতুন বিরোধ যোগ করে।","বিকল্প সাজানো সুবিধা-অসুবিধা স্পষ্ট করতে বা গোপনে সীমিত করতে পারে। কে বিকল্প বেছেছেন এবং কোনগুলো বাদ পড়েছে জানান।"],"correctOption":3,"explanationEn":"Choice structure can clarify trade-offs or quietly constrain them. Disclose who chose the options and which alternatives were dropped.","explanationBn":"বিকল্প সাজানো সুবিধা-অসুবিধা স্পষ্ট করতে বা গোপনে সীমিত করতে পারে। কে বিকল্প বেছেছেন এবং কোনগুলো বাদ পড়েছে জানান।"}]'::jsonb),
  ('play-to-peoples-fantasies', 'ef1c07f16011c34354872adfed4ce1ad',
    '[{"id":"identify-the-risk","questionEn":"A team wants to promise an unrealistically fast transformation. Which risk does this lesson most directly address?","questionBn":"একটি দল অবাস্তব দ্রুত পরিবর্তনের প্রতিশ্রুতি দিতে চায়। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Important trends can be missed when the evidence is hard to scan or compare.","Each team may be reacting to a different account of the same deadline changes.","An overlong answer can bury the new deadline and the next action.","An appealing promise can hide uncertainty about cost, time, and feasibility."],"optionsBn":["প্রমাণ দ্রুত পড়া বা তুলনা কঠিন হলে গুরুত্বপূর্ণ ধারা চোখ এড়াতে পারে।","একই সময়সীমা পরিবর্তন সম্পর্কে দুই দল ভিন্ন বর্ণনার ভিত্তিতে প্রতিক্রিয়া জানাতে পারে।","অতিরিক্ত দীর্ঘ উত্তরে নতুন সময়সীমা ও পরের কাজ চাপা পড়তে পারে।","আকর্ষণীয় প্রতিশ্রুতি খরচ, সময় ও বাস্তবসম্ভাব্যতার অনিশ্চয়তা আড়াল করতে পারে।"],"correctOption":3,"explanationEn":"An appealing promise can hide uncertainty about cost, time, and feasibility.","explanationBn":"আকর্ষণীয় প্রতিশ্রুতি খরচ, সময় ও বাস্তবসম্ভাব্যতার অনিশ্চয়তা আড়াল করতে পারে।"},{"id":"apply-the-boundary","questionEn":"A team wants to promise an unrealistically fast transformation. Which safeguard best prevents misusing this principle here?","questionBn":"একটি দল অবাস্তব দ্রুত পরিবর্তনের প্রতিশ্রুতি দিতে চায়। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["An appealing picture can help people understand a goal. State uncertainty and invite people to verify progress against the milestones.","Brevity works when the listener can act on what you said. Include dependencies or uncertainty if leaving them out would cause a bad decision.","Visibility is valuable when the audience can verify what changed. Exaggeration may win attention once and make the next announcement less credible.","Collect observations people agreed to share. Limit personal information and keep feedback anonymous when its disclosure could carry a cost."],"optionsBn":["আকর্ষণীয় চিত্র লক্ষ্য বুঝতে সাহায্য করে। অনিশ্চয়তা জানান এবং লক্ষ্যচিহ্ন ধরে অগ্রগতি যাচাইয়ের সুযোগ দিন।","শ্রোতা আপনার কথা থেকে কাজ করতে পারলেই সংক্ষিপ্ততা কার্যকর। বাদ দিলে ভুল সিদ্ধান্ত হতে পারে এমন নির্ভরতা বা অনিশ্চয়তা জানান।","দর্শক পরিবর্তন যাচাই করতে পারলে দৃশ্যমানতা মূল্যবান। অতিরঞ্জন একবার নজর কাড়লেও পরের ঘোষণার বিশ্বাসযোগ্যতা কমায়।","মানুষ যে তথ্য ভাগ করতে সম্মত হয়েছে তা সংগ্রহ করুন। ব্যক্তিগত তথ্য সীমিত রাখুন এবং প্রকাশে ক্ষতির আশঙ্কা থাকলে মতামত নামবিহীন রাখুন।"],"correctOption":0,"explanationEn":"An appealing picture can help people understand a goal. State uncertainty and invite people to verify progress against the milestones.","explanationBn":"আকর্ষণীয় চিত্র লক্ষ্য বুঝতে সাহায্য করে। অনিশ্চয়তা জানান এবং লক্ষ্যচিহ্ন ধরে অগ্রগতি যাচাইয়ের সুযোগ দিন।"}]'::jsonb),
  ('discover-each-mans-thumbscrew', 'df81ca083d33f394deed067e6206525b',
    '[{"id":"identify-the-risk","questionEn":"An employee is worried a proposed process will make their work invisible. Which risk does this lesson most directly address?","questionBn":"এক কর্মীর আশঙ্কা প্রস্তাবিত প্রক্রিয়ায় তাঁর কাজের দৃশ্যমানতা কমবে। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["A schedule that ignores caregiving constraints can generate resistance even when people support the goal.","Taking sole credit erodes contributors'' trust and willingness to help again.","A process may meet its formal goal while making someone''s contribution harder to see.","Opinions about efficiency may hold up in debate even when the actual results differ."],"optionsBn":["পরিচর্যার সীমা উপেক্ষা করা সময়সূচি লক্ষ্যে সমর্থন থাকলেও বিরোধ ডেকে আনতে পারে।","একাই কৃতিত্ব নিলে সহযোগীদের আস্থা ও আবার সাহায্য করার আগ্রহ কমে।","প্রক্রিয়া আনুষ্ঠানিক লক্ষ্য পূরণ করলেও কারও অবদান দেখা কঠিন করে দিতে পারে।","দক্ষতা নিয়ে মতামত তর্কে টিকে যেতে পারে, যদিও বাস্তব ফল ভিন্ন হয়।"],"correctOption":2,"explanationEn":"A process may meet its formal goal while making someone''s contribution harder to see.","explanationBn":"প্রক্রিয়া আনুষ্ঠানিক লক্ষ্য পূরণ করলেও কারও অবদান দেখা কঠিন করে দিতে পারে।"},{"id":"apply-the-boundary","questionEn":"An employee is worried a proposed process will make their work invisible. Which safeguard best prevents misusing this principle here?","questionBn":"এক কর্মীর আশঙ্কা প্রস্তাবিত প্রক্রিয়ায় তাঁর কাজের দৃশ্যমানতা কমবে। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Define the comparison before you see the numbers. Include error rate and accessibility alongside speed so the faster template does not disguise worse service.","Understanding someone''s concern helps you negotiate a workable agreement. Using private vulnerabilities as leverage will often destroy the trust the agreement needs.","An honest disclosure or generous gesture is evidence of that act alone. Check the broader deal, including price, conditions, and obligations.","Tact improves the chance that evidence is heard. Use formal reporting in situations that require accountability or independent review."],"optionsBn":["ফল দেখার আগে তুলনার মানদণ্ড ঠিক করুন। গতির পাশাপাশি ভুলের হার ও প্রবেশগম্যতা ধরুন যাতে দ্রুততর টেমপ্লেট খারাপ সেবা ঢেকে না দেয়।","কারও উদ্বেগ বুঝলে কার্যকর সমঝোতা করা সহজ হয়। ব্যক্তিগত দুর্বলতা চাপ হিসেবে ব্যবহার করলে সমঝোতার জন্য দরকারি আস্থা নষ্ট হতে পারে।","সৎ স্বীকারোক্তি বা উদারতা শুধু সেই কাজের প্রমাণ। দাম, শর্ত ও দায়বদ্ধতাসহ পুরো চুক্তি যাচাই করুন।","কৌশলী উপস্থাপনা প্রমাণ শোনার সম্ভাবনা বাড়ায়। জবাবদিহি বা স্বাধীন পর্যালোচনা দরকার হলে আনুষ্ঠানিকভাবে জানান।"],"correctOption":1,"explanationEn":"Understanding someone''s concern helps you negotiate a workable agreement. Using private vulnerabilities as leverage will often destroy the trust the agreement needs.","explanationBn":"কারও উদ্বেগ বুঝলে কার্যকর সমঝোতা করা সহজ হয়। ব্যক্তিগত দুর্বলতা চাপ হিসেবে ব্যবহার করলে সমঝোতার জন্য দরকারি আস্থা নষ্ট হতে পারে।"}]'::jsonb),
  ('be-royal-in-your-own-fashion', 'd802ba9fd2b1ea91703811c00cd365d9',
    '[{"id":"identify-the-risk","questionEn":"You are asked to lead a meeting with more senior colleagues. Which risk does this lesson most directly address?","questionBn":"ঊর্ধ্বতন সহকর্মীদের একটি সভা পরিচালনার দায়িত্ব পেয়েছেন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Chasing a closed decision can consume the time available for an open opportunity.","A meeting without a clear process can allow status to determine whose concerns are heard.","A zero price can conceal obligations that have a real cost later.","Copying a predecessor may tie the new director''s work to conditions that have changed."],"optionsBn":["বন্ধ সিদ্ধান্তের পেছনে ছুটলে খোলা সুযোগের জন্য সময় ফুরিয়ে যেতে পারে।","স্পষ্ট পদ্ধতি না থাকলে কার কথা শোনা হবে তা সভায় পদমর্যাদা নির্ধারণ করতে পারে।","শূন্য দাম ভবিষ্যতের বাস্তব ব্যয়যুক্ত দায়বদ্ধতা আড়াল করতে পারে।","পূর্বসূরির অনুকরণ নতুন পরিচালকের কাজকে বদলে যাওয়া পরিস্থিতির সঙ্গে বেঁধে দিতে পারে।"],"correctOption":1,"explanationEn":"A meeting without a clear process can allow status to determine whose concerns are heard.","explanationBn":"স্পষ্ট পদ্ধতি না থাকলে কার কথা শোনা হবে তা সভায় পদমর্যাদা নির্ধারণ করতে পারে।"},{"id":"apply-the-boundary","questionEn":"You are asked to lead a meeting with more senior colleagues. Which safeguard best prevents misusing this principle here?","questionBn":"ঊর্ধ্বতন সহকর্মীদের একটি সভা পরিচালনার দায়িত্ব পেয়েছেন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["A predecessor''s methods may fit a different set of constraints. Keep the parts that still work and explain the evidence for changing the rest.","Define the stopping rule before success changes your incentives. A new opportunity needs a fresh decision with its own costs and risks.","Calm authority comes from owning a decision process. Make space for relevant objections, especially from people with lower status.","The useful boundary is about recurring behavior and its effect on the team. Distress by itself calls for empathy and appropriate support."],"optionsBn":["পূর্বসূরির পদ্ধতি ভিন্ন সীমাবদ্ধতার সঙ্গে মানানসই হতে পারে। যা এখনো চলে তা রাখুন এবং বাকিটা বদলের প্রমাণ ব্যাখ্যা করুন।","সাফল্য আপনার প্রণোদনা বদলানোর আগে থামার নিয়ম ঠিক করুন। নতুন সুযোগের ব্যয় ও ঝুঁকি ধরে নতুন সিদ্ধান্ত নিন।","শান্ত কর্তৃত্ব আসে সিদ্ধান্তের প্রক্রিয়ার দায় নেওয়া থেকে। প্রাসঙ্গিক আপত্তির সুযোগ রাখুন, বিশেষ করে কম ক্ষমতাসম্পন্ন মানুষের জন্য।","সীমা টানার কারণ হলো পুনরাবৃত্ত আচরণ ও দলের ওপর তার প্রভাব। কষ্টে থাকা মানুষের প্রতি সহমর্মিতা ও উপযুক্ত সহায়তা দিন।"],"correctOption":2,"explanationEn":"Calm authority comes from owning a decision process. Make space for relevant objections, especially from people with lower status.","explanationBn":"শান্ত কর্তৃত্ব আসে সিদ্ধান্তের প্রক্রিয়ার দায় নেওয়া থেকে। প্রাসঙ্গিক আপত্তির সুযোগ রাখুন, বিশেষ করে কম ক্ষমতাসম্পন্ন মানুষের জন্য।"}]'::jsonb),
  ('master-the-art-of-timing', 'bbf331cd256f573d567f2988076731ea',
    '[{"id":"identify-the-risk","questionEn":"A major proposal is ready while your reviewers are handling an outage. Which risk does this lesson most directly address?","questionBn":"বড় একটি প্রস্তাব প্রস্তুত, কিন্তু পর্যালোচকেরা সেবা বিভ্রাট সামলাচ্ছেন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Reviewers handling an urgent incident may have too little attention for a major proposal.","Ignoring unfamiliar communication norms may create friction before substantive issues get a hearing.","Changing several tools at once makes disruption harder to diagnose and reverse.","Keeping a familiar method after rules change can put the outcome and compliance at risk."],"optionsBn":["জরুরি ঘটনা সামলানো পর্যালোচকেরা বড় প্রস্তাবে যথেষ্ট মনোযোগ দিতে নাও পারেন।","অপরিচিত যোগাযোগরীতি উপেক্ষা করলে মূল বিষয় শোনার আগেই বিরোধ তৈরি হতে পারে।","একসঙ্গে কয়েকটি সরঞ্জাম বদলালে বিঘ্নের কারণ ধরা ও পূর্বাবস্থায় ফেরা কঠিন হয়।","নিয়ম বদলের পরও পরিচিত পদ্ধতি ধরে রাখলে ফল ও নিয়মপালন দুটিই ঝুঁকিতে পড়তে পারে।"],"correctOption":0,"explanationEn":"Reviewers handling an urgent incident may have too little attention for a major proposal.","explanationBn":"জরুরি ঘটনা সামলানো পর্যালোচকেরা বড় প্রস্তাবে যথেষ্ট মনোযোগ দিতে নাও পারেন।"},{"id":"apply-the-boundary","questionEn":"A major proposal is ready while your reviewers are handling an outage. Which safeguard best prevents misusing this principle here?","questionBn":"বড় একটি প্রস্তাব প্রস্তুত, কিন্তু পর্যালোচকেরা সেবা বিভ্রাট সামলাচ্ছেন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Flexibility is about changing methods while honoring durable commitments. Measure alternatives against the same outcome so adaptation remains accountable.","Accept only a reversible compromise whose review date is real. A vague promise to revisit can turn a temporary concession into a permanent one.","Stop investing attention after the answer is settled, but keep lessons that improve the next attempt. Persistent problems still need a responsible escalation path.","Timing involves both opportunity and cost of delay. Set a review date rather than indefinitely waiting for a perfect moment."],"optionsBn":["নমনীয়তা হলো দীর্ঘমেয়াদি প্রতিশ্রুতি রেখে পদ্ধতি বদলানো। একই ফলের মাপকাঠি দিয়ে বিকল্প বিচার করলে অভিযোজন জবাবদিহির আওতায় থাকে।","যে সাময়িক সমঝোতা ফিরিয়ে নেওয়া যায় এবং যার পর্যালোচনার তারিখ ঠিক আছে সেটিই নিন। অস্পষ্ট আশ্বাসে সাময়িক ছাড় স্থায়ী হতে পারে।","সিদ্ধান্ত চূড়ান্ত হলে সময় ব্যয় থামান, তবে পরের চেষ্টা উন্নত করে এমন শিক্ষা রাখুন। চলমান সমস্যার জন্য দায়িত্বপূর্ণভাবে বিষয় তোলার পথ দরকার।","সময় বাছাইয়ে সুযোগ ও দেরির ব্যয় দুটোই আছে। আদর্শ মুহূর্তের জন্য অনির্দিষ্ট অপেক্ষা না করে পর্যালোচনার তারিখ ঠিক করুন।"],"correctOption":3,"explanationEn":"Timing involves both opportunity and cost of delay. Set a review date rather than indefinitely waiting for a perfect moment.","explanationBn":"সময় বাছাইয়ে সুযোগ ও দেরির ব্যয় দুটোই আছে। আদর্শ মুহূর্তের জন্য অনির্দিষ্ট অপেক্ষা না করে পর্যালোচনার তারিখ ঠিক করুন।"}]'::jsonb),
  ('disdain-things-you-cannot-have', 'e8c3dca17650285dd8c0f75e7bcb83ab',
    '[{"id":"identify-the-risk","questionEn":"A rejected pitch is consuming time needed for a better opportunity. Which risk does this lesson most directly address?","questionBn":"প্রত্যাখ্যাত প্রস্তাব একটি ভালো সুযোগের জন্য দরকারি সময় নিয়ে নিচ্ছে। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["A zero price can conceal obligations that have a real cost later.","Copying a predecessor may tie the new director''s work to conditions that have changed.","Additional demands after reaching the goal can reopen a deal that was already settled.","Chasing a closed decision can consume the time available for an open opportunity."],"optionsBn":["শূন্য দাম ভবিষ্যতের বাস্তব ব্যয়যুক্ত দায়বদ্ধতা আড়াল করতে পারে।","পূর্বসূরির অনুকরণ নতুন পরিচালকের কাজকে বদলে যাওয়া পরিস্থিতির সঙ্গে বেঁধে দিতে পারে।","লক্ষ্য পূরণের পর নতুন দাবি মীমাংসিত চুক্তি আবার আলোচনায় টেনে আনতে পারে।","বন্ধ সিদ্ধান্তের পেছনে ছুটলে খোলা সুযোগের জন্য সময় ফুরিয়ে যেতে পারে।"],"correctOption":3,"explanationEn":"Chasing a closed decision can consume the time available for an open opportunity.","explanationBn":"বন্ধ সিদ্ধান্তের পেছনে ছুটলে খোলা সুযোগের জন্য সময় ফুরিয়ে যেতে পারে।"},{"id":"apply-the-boundary","questionEn":"A rejected pitch is consuming time needed for a better opportunity. Which safeguard best prevents misusing this principle here?","questionBn":"প্রত্যাখ্যাত প্রস্তাব একটি ভালো সুযোগের জন্য দরকারি সময় নিয়ে নিচ্ছে। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Stop investing attention after the answer is settled, but keep lessons that improve the next attempt. Persistent problems still need a responsible escalation path.","Define the stopping rule before success changes your incentives. A new opportunity needs a fresh decision with its own costs and risks.","The useful boundary is about recurring behavior and its effect on the team. Distress by itself calls for empathy and appropriate support.","More contacts help only when useful information can travel both ways. Give partner teams a clear path for reporting problems."],"optionsBn":["সিদ্ধান্ত চূড়ান্ত হলে সময় ব্যয় থামান, তবে পরের চেষ্টা উন্নত করে এমন শিক্ষা রাখুন। চলমান সমস্যার জন্য দায়িত্বপূর্ণভাবে বিষয় তোলার পথ দরকার।","সাফল্য আপনার প্রণোদনা বদলানোর আগে থামার নিয়ম ঠিক করুন। নতুন সুযোগের ব্যয় ও ঝুঁকি ধরে নতুন সিদ্ধান্ত নিন।","সীমা টানার কারণ হলো পুনরাবৃত্ত আচরণ ও দলের ওপর তার প্রভাব। কষ্টে থাকা মানুষের প্রতি সহমর্মিতা ও উপযুক্ত সহায়তা দিন।","উপকারী তথ্য দুই দিকেই চললে যোগাযোগ বাড়ানোর লাভ আছে। অন্য দলকে সমস্যা জানানোর স্পষ্ট পথ দিন।"],"correctOption":0,"explanationEn":"Stop investing attention after the answer is settled, but keep lessons that improve the next attempt. Persistent problems still need a responsible escalation path.","explanationBn":"সিদ্ধান্ত চূড়ান্ত হলে সময় ব্যয় থামান, তবে পরের চেষ্টা উন্নত করে এমন শিক্ষা রাখুন। চলমান সমস্যার জন্য দায়িত্বপূর্ণভাবে বিষয় তোলার পথ দরকার।"}]'::jsonb),
  ('create-compelling-spectacles', '2dac1d8ed72c354719a9c5f31ce0732a',
    '[{"id":"identify-the-risk","questionEn":"A long report makes a safety trend difficult to see. Which risk does this lesson most directly address?","questionBn":"দীর্ঘ প্রতিবেদনে নিরাপত্তাজনিত একটি ধারা বোঝা কঠিন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Each team may be reacting to a different account of the same deadline changes.","An overlong answer can bury the new deadline and the next action.","Important trends can be missed when the evidence is hard to scan or compare.","An overlooked improvement may fail to reach the people who benefit from it."],"optionsBn":["একই সময়সীমা পরিবর্তন সম্পর্কে দুই দল ভিন্ন বর্ণনার ভিত্তিতে প্রতিক্রিয়া জানাতে পারে।","অতিরিক্ত দীর্ঘ উত্তরে নতুন সময়সীমা ও পরের কাজ চাপা পড়তে পারে।","প্রমাণ দ্রুত পড়া বা তুলনা কঠিন হলে গুরুত্বপূর্ণ ধারা চোখ এড়াতে পারে।","নজর এড়ানো উন্নতি যাঁদের কাজে লাগবে তাঁদের কাছে নাও পৌঁছাতে পারে।"],"correctOption":2,"explanationEn":"Important trends can be missed when the evidence is hard to scan or compare.","explanationBn":"প্রমাণ দ্রুত পড়া বা তুলনা কঠিন হলে গুরুত্বপূর্ণ ধারা চোখ এড়াতে পারে।"},{"id":"apply-the-boundary","questionEn":"A long report makes a safety trend difficult to see. Which safeguard best prevents misusing this principle here?","questionBn":"দীর্ঘ প্রতিবেদনে নিরাপত্তাজনিত একটি ধারা বোঝা কঠিন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Visibility is valuable when the audience can verify what changed. Exaggeration may win attention once and make the next announcement less credible.","A memorable visual should make the relevant evidence easier to inspect. Label scale, missing data, and uncertainty when they affect interpretation.","Collect observations people agreed to share. Limit personal information and keep feedback anonymous when its disclosure could carry a cost.","Basic questions test jargon and hidden assumptions. They are most useful when you can also check the answers against independent evidence."],"optionsBn":["দর্শক পরিবর্তন যাচাই করতে পারলে দৃশ্যমানতা মূল্যবান। অতিরঞ্জন একবার নজর কাড়লেও পরের ঘোষণার বিশ্বাসযোগ্যতা কমায়।","স্মরণীয় দৃশ্য প্রাসঙ্গিক প্রমাণ যাচাই সহজ করবে। ব্যাখ্যায় প্রভাব ফেললে স্কেল, অনুপস্থিত তথ্য ও অনিশ্চয়তা চিহ্নিত করুন।","মানুষ যে তথ্য ভাগ করতে সম্মত হয়েছে তা সংগ্রহ করুন। ব্যক্তিগত তথ্য সীমিত রাখুন এবং প্রকাশে ক্ষতির আশঙ্কা থাকলে মতামত নামবিহীন রাখুন।","সহজ প্রশ্ন দুর্বোধ্য পরিভাষা ও গোপন অনুমান যাচাই করে। উত্তর স্বাধীন প্রমাণের সঙ্গে মিলিয়ে দেখতে পারলে এগুলো আরও কার্যকর।"],"correctOption":1,"explanationEn":"A memorable visual should make the relevant evidence easier to inspect. Label scale, missing data, and uncertainty when they affect interpretation.","explanationBn":"স্মরণীয় দৃশ্য প্রাসঙ্গিক প্রমাণ যাচাই সহজ করবে। ব্যাখ্যায় প্রভাব ফেললে স্কেল, অনুপস্থিত তথ্য ও অনিশ্চয়তা চিহ্নিত করুন।"}]'::jsonb),
  ('think-as-you-like-but-behave-like-others', '08c0b22bbdf1d55c4b0d098355980993',
    '[{"id":"identify-the-risk","questionEn":"You are new to a team with unfamiliar communication conventions. Which risk does this lesson most directly address?","questionBn":"অপরিচিত যোগাযোগরীতি আছে এমন একটি দলে আপনি নতুন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Changing several tools at once makes disruption harder to diagnose and reverse.","Ignoring unfamiliar communication norms may create friction before substantive issues get a hearing.","Keeping a familiar method after rules change can put the outcome and compliance at risk.","Confrontation at a disadvantage can consume resources without improving your position."],"optionsBn":["একসঙ্গে কয়েকটি সরঞ্জাম বদলালে বিঘ্নের কারণ ধরা ও পূর্বাবস্থায় ফেরা কঠিন হয়।","অপরিচিত যোগাযোগরীতি উপেক্ষা করলে মূল বিষয় শোনার আগেই বিরোধ তৈরি হতে পারে।","নিয়ম বদলের পরও পরিচিত পদ্ধতি ধরে রাখলে ফল ও নিয়মপালন দুটিই ঝুঁকিতে পড়তে পারে।","দুর্বল অবস্থায় সরাসরি বিরোধে সম্পদ ক্ষয় হলেও অবস্থার উন্নতি নাও হতে পারে।"],"correctOption":1,"explanationEn":"Ignoring unfamiliar communication norms may create friction before substantive issues get a hearing.","explanationBn":"অপরিচিত যোগাযোগরীতি উপেক্ষা করলে মূল বিষয় শোনার আগেই বিরোধ তৈরি হতে পারে।"},{"id":"apply-the-boundary","questionEn":"You are new to a team with unfamiliar communication conventions. Which safeguard best prevents misusing this principle here?","questionBn":"অপরিচিত যোগাযোগরীতি আছে এমন একটি দলে আপনি নতুন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Accept only a reversible compromise whose review date is real. A vague promise to revisit can turn a temporary concession into a permanent one.","Timing involves both opportunity and cost of delay. Set a review date rather than indefinitely waiting for a perfect moment.","Adapting to ordinary norms can improve cooperation without changing your judgment. Challenge a norm openly if it violates policy or excludes people.","Agitation can reveal how a discussion is being steered, but it also lowers judgment. Slow the exchange and distinguish evidence from provocation."],"optionsBn":["যে সাময়িক সমঝোতা ফিরিয়ে নেওয়া যায় এবং যার পর্যালোচনার তারিখ ঠিক আছে সেটিই নিন। অস্পষ্ট আশ্বাসে সাময়িক ছাড় স্থায়ী হতে পারে।","সময় বাছাইয়ে সুযোগ ও দেরির ব্যয় দুটোই আছে। আদর্শ মুহূর্তের জন্য অনির্দিষ্ট অপেক্ষা না করে পর্যালোচনার তারিখ ঠিক করুন।","সাধারণ রীতির সঙ্গে মানিয়ে বিচার অক্ষুণ্ণ রেখেও সহযোগিতা বাড়ানো যায়। নিয়ম ভাঙে বা মানুষকে বাদ দেয় এমন রীতি প্রকাশ্যে প্রশ্ন করুন।","উত্তেজনা আলোচনা কীভাবে চালিত হচ্ছে তা দেখায়, কিন্তু বিচার দুর্বলও করে। গতি কমিয়ে উসকানি থেকে প্রমাণ আলাদা করুন।"],"correctOption":2,"explanationEn":"Adapting to ordinary norms can improve cooperation without changing your judgment. Challenge a norm openly if it violates policy or excludes people.","explanationBn":"সাধারণ রীতির সঙ্গে মানিয়ে বিচার অক্ষুণ্ণ রেখেও সহযোগিতা বাড়ানো যায়। নিয়ম ভাঙে বা মানুষকে বাদ দেয় এমন রীতি প্রকাশ্যে প্রশ্ন করুন।"}]'::jsonb),
  ('stir-up-waters-to-catch-fish', '9944817b16ac6645c7ad6dc344caf814',
    '[{"id":"identify-the-risk","questionEn":"A negotiation becomes heated after an accusation. Which risk does this lesson most directly address?","questionBn":"অভিযোগ ওঠার পর একটি আলোচনা উত্তপ্ত হয়ে উঠেছে। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Emotional escalation makes accusations feel more persuasive than verifiable evidence.","Concentrating approvals in one role can stall the entire group''s routine work.","Announcing tentative terms can reduce room to negotiate or create premature expectations.","Repeated requests can consume goodwill without giving invitees a reason to engage."],"optionsBn":["আবেগ বেড়ে গেলে যাচাইযোগ্য প্রমাণের চেয়ে অভিযোগ বেশি বিশ্বাসযোগ্য মনে হতে পারে।","অনুমোদন একটি পদে কেন্দ্রীভূত করলে পুরো দলের নিয়মিত কাজ থেমে যেতে পারে।","অস্থায়ী শর্ত ঘোষণা করলে আলোচনার সুযোগ কমে বা অকালে প্রত্যাশা তৈরি হয়।","বারবার অনুরোধে সদিচ্ছা কমতে পারে, অথচ সাড়া দেওয়ার কারণ তৈরি হয় না।"],"correctOption":0,"explanationEn":"Emotional escalation makes accusations feel more persuasive than verifiable evidence.","explanationBn":"আবেগ বেড়ে গেলে যাচাইযোগ্য প্রমাণের চেয়ে অভিযোগ বেশি বিশ্বাসযোগ্য মনে হতে পারে।"},{"id":"apply-the-boundary","questionEn":"A negotiation becomes heated after an accusation. Which safeguard best prevents misusing this principle here?","questionBn":"অভিযোগ ওঠার পর একটি আলোচনা উত্তপ্ত হয়ে উঠেছে। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["An invitation should have value even if the recipient declines the larger proposal. Avoid hidden obligations that make the first interaction feel deceptive.","A durable settlement removes the circumstances that recreate the conflict. Retaliation leaves the root cause in place and adds another dispute.","Keep operational obligations predictable even when tactics change. People who rely on you need stable deadlines and a way to reach you.","Agitation can reveal how a discussion is being steered, but it also lowers judgment. Slow the exchange and distinguish evidence from provocation."],"optionsBn":["বড় প্রস্তাব প্রত্যাখ্যান করলেও আমন্ত্রণটি প্রাপকের কাজে লাগা উচিত। প্রথম যোগাযোগকে প্রতারণামূলক করে এমন গোপন শর্ত এড়ান।","টেকসই সমাধান সংঘাত আবার তৈরি হওয়ার পরিস্থিতি দূর করে। প্রতিশোধ মূল কারণ রেখে নতুন বিরোধ যোগ করে।","কৌশল বদলালেও কাজের দায়বদ্ধতা স্থির রাখুন। নির্ভরশীল মানুষের স্থির সময়সীমা ও যোগাযোগের পথ দরকার।","উত্তেজনা আলোচনা কীভাবে চালিত হচ্ছে তা দেখায়, কিন্তু বিচার দুর্বলও করে। গতি কমিয়ে উসকানি থেকে প্রমাণ আলাদা করুন।"],"correctOption":3,"explanationEn":"Agitation can reveal how a discussion is being steered, but it also lowers judgment. Slow the exchange and distinguish evidence from provocation.","explanationBn":"উত্তেজনা আলোচনা কীভাবে চালিত হচ্ছে তা দেখায়, কিন্তু বিচার দুর্বলও করে। গতি কমিয়ে উসকানি থেকে প্রমাণ আলাদা করুন।"}]'::jsonb),
  ('despise-the-free-lunch', 'c748460f61d2c956a47d7e0fbfad13cd',
    '[{"id":"identify-the-risk","questionEn":"A vendor offers free equipment in exchange for unspecified future access. Which risk does this lesson most directly address?","questionBn":"ভবিষ্যতে অস্পষ্ট প্রবেশাধিকারের বিনিময়ে বিক্রেতা বিনামূল্যে সরঞ্জাম দিতে চান। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Copying a predecessor may tie the new director''s work to conditions that have changed.","Additional demands after reaching the goal can reopen a deal that was already settled.","Recurring venting can crowd out coordination without solving the source of distress.","A zero price can conceal obligations that have a real cost later."],"optionsBn":["পূর্বসূরির অনুকরণ নতুন পরিচালকের কাজকে বদলে যাওয়া পরিস্থিতির সঙ্গে বেঁধে দিতে পারে।","লক্ষ্য পূরণের পর নতুন দাবি মীমাংসিত চুক্তি আবার আলোচনায় টেনে আনতে পারে।","বারবার অভিযোগে সমন্বয়ের আলোচনা চাপা পড়ে, অথচ কষ্টের উৎস দূর হয় না।","শূন্য দাম ভবিষ্যতের বাস্তব ব্যয়যুক্ত দায়বদ্ধতা আড়াল করতে পারে।"],"correctOption":3,"explanationEn":"A zero price can conceal obligations that have a real cost later.","explanationBn":"শূন্য দাম ভবিষ্যতের বাস্তব ব্যয়যুক্ত দায়বদ্ধতা আড়াল করতে পারে।"},{"id":"apply-the-boundary","questionEn":"A vendor offers free equipment in exchange for unspecified future access. Which safeguard best prevents misusing this principle here?","questionBn":"ভবিষ্যতে অস্পষ্ট প্রবেশাধিকারের বিনিময়ে বিক্রেতা বিনামূল্যে সরঞ্জাম দিতে চান। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Calculate the cost across the whole relationship. Check exclusivity, future dependence, and data access alongside the headline price.","The useful boundary is about recurring behavior and its effect on the team. Distress by itself calls for empathy and appropriate support.","More contacts help only when useful information can travel both ways. Give partner teams a clear path for reporting problems.","A new role becomes credible through repeated behavior. Communicate which responsibilities changed and who now owns your former work."],"optionsBn":["পুরো সম্পর্কের ব্যয় হিসাব করুন। ঘোষিত দামের পাশাপাশি একচেটিয়া শর্ত, ভবিষ্যৎ নির্ভরতা ও তথ্যের প্রবেশাধিকার যাচাই করুন।","সীমা টানার কারণ হলো পুনরাবৃত্ত আচরণ ও দলের ওপর তার প্রভাব। কষ্টে থাকা মানুষের প্রতি সহমর্মিতা ও উপযুক্ত সহায়তা দিন।","উপকারী তথ্য দুই দিকেই চললে যোগাযোগ বাড়ানোর লাভ আছে। অন্য দলকে সমস্যা জানানোর স্পষ্ট পথ দিন।","পুনরাবৃত্ত আচরণে নতুন ভূমিকা বিশ্বাসযোগ্য হয়। কোন দায়িত্ব বদলেছে এবং আগের কাজ এখন কার তা জানান।"],"correctOption":0,"explanationEn":"Calculate the cost across the whole relationship. Check exclusivity, future dependence, and data access alongside the headline price.","explanationBn":"পুরো সম্পর্কের ব্যয় হিসাব করুন। ঘোষিত দামের পাশাপাশি একচেটিয়া শর্ত, ভবিষ্যৎ নির্ভরতা ও তথ্যের প্রবেশাধিকার যাচাই করুন।"}]'::jsonb),
  ('avoid-stepping-into-a-great-mans-shoes', 'dd7f92b66766815c48884a404ddb93a5',
    '[{"id":"identify-the-risk","questionEn":"You replace a popular director whose programme had a distinctive style. Which risk does this lesson most directly address?","questionBn":"নিজস্ব শৈলীর কর্মসূচি চালানো এক জনপ্রিয় পরিচালকের স্থলাভিষিক্ত হয়েছেন। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Additional demands after reaching the goal can reopen a deal that was already settled.","Recurring venting can crowd out coordination without solving the source of distress.","Copying a predecessor may tie the new director''s work to conditions that have changed.","Isolation cuts off early warnings and leaves the team responding late."],"optionsBn":["লক্ষ্য পূরণের পর নতুন দাবি মীমাংসিত চুক্তি আবার আলোচনায় টেনে আনতে পারে।","বারবার অভিযোগে সমন্বয়ের আলোচনা চাপা পড়ে, অথচ কষ্টের উৎস দূর হয় না।","পূর্বসূরির অনুকরণ নতুন পরিচালকের কাজকে বদলে যাওয়া পরিস্থিতির সঙ্গে বেঁধে দিতে পারে।","বিচ্ছিন্নতায় আগাম সতর্কতা পৌঁছায় না, ফলে দল দেরিতে সাড়া দেয়।"],"correctOption":2,"explanationEn":"Copying a predecessor may tie the new director''s work to conditions that have changed.","explanationBn":"পূর্বসূরির অনুকরণ নতুন পরিচালকের কাজকে বদলে যাওয়া পরিস্থিতির সঙ্গে বেঁধে দিতে পারে।"},{"id":"apply-the-boundary","questionEn":"You replace a popular director whose programme had a distinctive style. Which safeguard best prevents misusing this principle here?","questionBn":"নিজস্ব শৈলীর কর্মসূচি চালানো এক জনপ্রিয় পরিচালকের স্থলাভিষিক্ত হয়েছেন। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["More contacts help only when useful information can travel both ways. Give partner teams a clear path for reporting problems.","A predecessor''s methods may fit a different set of constraints. Keep the parts that still work and explain the evidence for changing the rest.","A new role becomes credible through repeated behavior. Communicate which responsibilities changed and who now owns your former work.","Calm authority comes from owning a decision process. Make space for relevant objections, especially from people with lower status."],"optionsBn":["উপকারী তথ্য দুই দিকেই চললে যোগাযোগ বাড়ানোর লাভ আছে। অন্য দলকে সমস্যা জানানোর স্পষ্ট পথ দিন।","পূর্বসূরির পদ্ধতি ভিন্ন সীমাবদ্ধতার সঙ্গে মানানসই হতে পারে। যা এখনো চলে তা রাখুন এবং বাকিটা বদলের প্রমাণ ব্যাখ্যা করুন।","পুনরাবৃত্ত আচরণে নতুন ভূমিকা বিশ্বাসযোগ্য হয়। কোন দায়িত্ব বদলেছে এবং আগের কাজ এখন কার তা জানান।","শান্ত কর্তৃত্ব আসে সিদ্ধান্তের প্রক্রিয়ার দায় নেওয়া থেকে। প্রাসঙ্গিক আপত্তির সুযোগ রাখুন, বিশেষ করে কম ক্ষমতাসম্পন্ন মানুষের জন্য।"],"correctOption":1,"explanationEn":"A predecessor''s methods may fit a different set of constraints. Keep the parts that still work and explain the evidence for changing the rest.","explanationBn":"পূর্বসূরির পদ্ধতি ভিন্ন সীমাবদ্ধতার সঙ্গে মানানসই হতে পারে। যা এখনো চলে তা রাখুন এবং বাকিটা বদলের প্রমাণ ব্যাখ্যা করুন।"}]'::jsonb),
  ('strike-the-shepherd-and-the-sheep-will-scatter', '454e1e011b0daa147bb171f6a1ba0f2c',
    '[{"id":"identify-the-risk","questionEn":"A stalled committee relies on a single person for every approval. Which risk does this lesson most directly address?","questionBn":"স্থবির একটি কমিটির প্রতিটি অনুমোদনের জন্য একজনের ওপর নির্ভর করতে হয়। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Announcing tentative terms can reduce room to negotiate or create premature expectations.","Concentrating approvals in one role can stall the entire group''s routine work.","Repeated requests can consume goodwill without giving invitees a reason to engage.","A temporary truce may fail because the handoff still recreates the conflict."],"optionsBn":["অস্থায়ী শর্ত ঘোষণা করলে আলোচনার সুযোগ কমে বা অকালে প্রত্যাশা তৈরি হয়।","অনুমোদন একটি পদে কেন্দ্রীভূত করলে পুরো দলের নিয়মিত কাজ থেমে যেতে পারে।","বারবার অনুরোধে সদিচ্ছা কমতে পারে, অথচ সাড়া দেওয়ার কারণ তৈরি হয় না।","সাময়িক সমঝোতা ভেঙে যেতে পারে, কারণ দায়িত্ব হস্তান্তরেই বিরোধ আবার তৈরি হয়।"],"correctOption":1,"explanationEn":"Concentrating approvals in one role can stall the entire group''s routine work.","explanationBn":"অনুমোদন একটি পদে কেন্দ্রীভূত করলে পুরো দলের নিয়মিত কাজ থেমে যেতে পারে।"},{"id":"apply-the-boundary","questionEn":"A stalled committee relies on a single person for every approval. Which safeguard best prevents misusing this principle here?","questionBn":"স্থবির একটি কমিটির প্রতিটি অনুমোদনের জন্য একজনের ওপর নির্ভর করতে হয়। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["A durable settlement removes the circumstances that recreate the conflict. Retaliation leaves the root cause in place and adds another dispute.","Keep operational obligations predictable even when tactics change. People who rely on you need stable deadlines and a way to reach you.","Test whether a single role is an actual bottleneck before redistributing authority. Improve the process without targeting the person who held the role.","Preserve independent judgment while meeting commitments already made. Tell people when and how a decision will actually be taken."],"optionsBn":["টেকসই সমাধান সংঘাত আবার তৈরি হওয়ার পরিস্থিতি দূর করে। প্রতিশোধ মূল কারণ রেখে নতুন বিরোধ যোগ করে।","কৌশল বদলালেও কাজের দায়বদ্ধতা স্থির রাখুন। নির্ভরশীল মানুষের স্থির সময়সীমা ও যোগাযোগের পথ দরকার।","কর্তৃত্ব ভাগ করার আগে একক ভূমিকাটি সত্যিই বাধা কি না যাচাই করুন। পদধারী ব্যক্তিকে লক্ষ্য না করে প্রক্রিয়া উন্নত করুন।","আগে দেওয়া প্রতিশ্রুতি রেখে স্বাধীন বিচার বজায় রাখুন। সিদ্ধান্ত কখন ও কীভাবে হবে তা সংশ্লিষ্টদের জানান।"],"correctOption":2,"explanationEn":"Test whether a single role is an actual bottleneck before redistributing authority. Improve the process without targeting the person who held the role.","explanationBn":"কর্তৃত্ব ভাগ করার আগে একক ভূমিকাটি সত্যিই বাধা কি না যাচাই করুন। পদধারী ব্যক্তিকে লক্ষ্য না করে প্রক্রিয়া উন্নত করুন।"}]'::jsonb),
  ('work-on-the-hearts-and-minds-of-others', 'f1a724be781390822eeea6dfb4ff68d0',
    '[{"id":"identify-the-risk","questionEn":"A team resists a schedule change because it affects caregiving. Which risk does this lesson most directly address?","questionBn":"পরিচর্যার দায়িত্বে প্রভাব পড়বে বলে একটি দল সময়সূচি বদলের বিরোধিতা করছে। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["A schedule that ignores caregiving constraints can generate resistance even when people support the goal.","Taking sole credit erodes contributors'' trust and willingness to help again.","Opinions about efficiency may hold up in debate even when the actual results differ.","A gift can influence judgment about an offer whose terms still need scrutiny."],"optionsBn":["পরিচর্যার সীমা উপেক্ষা করা সময়সূচি লক্ষ্যে সমর্থন থাকলেও বিরোধ ডেকে আনতে পারে।","একাই কৃতিত্ব নিলে সহযোগীদের আস্থা ও আবার সাহায্য করার আগ্রহ কমে।","দক্ষতা নিয়ে মতামত তর্কে টিকে যেতে পারে, যদিও বাস্তব ফল ভিন্ন হয়।","উপহার এমন প্রস্তাবের বিচারকে প্রভাবিত করতে পারে, যার শর্ত এখনো যাচাই করা দরকার।"],"correctOption":0,"explanationEn":"A schedule that ignores caregiving constraints can generate resistance even when people support the goal.","explanationBn":"পরিচর্যার সীমা উপেক্ষা করা সময়সূচি লক্ষ্যে সমর্থন থাকলেও বিরোধ ডেকে আনতে পারে।"},{"id":"apply-the-boundary","questionEn":"A team resists a schedule change because it affects caregiving. Which safeguard best prevents misusing this principle here?","questionBn":"পরিচর্যার দায়িত্বে প্রভাব পড়বে বলে একটি দল সময়সূচি বদলের বিরোধিতা করছে। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["An honest disclosure or generous gesture is evidence of that act alone. Check the broader deal, including price, conditions, and obligations.","Tact improves the chance that evidence is heard. Use formal reporting in situations that require accountability or independent review.","Belonging can motivate cooperation, but demands for uncritical loyalty undermine judgment. Look for transparent claims, safe disagreement, and accountability.","Concern is information about a real implementation constraint. Demonstrate that you heard it by showing what changed and why."],"optionsBn":["সৎ স্বীকারোক্তি বা উদারতা শুধু সেই কাজের প্রমাণ। দাম, শর্ত ও দায়বদ্ধতাসহ পুরো চুক্তি যাচাই করুন।","কৌশলী উপস্থাপনা প্রমাণ শোনার সম্ভাবনা বাড়ায়। জবাবদিহি বা স্বাধীন পর্যালোচনা দরকার হলে আনুষ্ঠানিকভাবে জানান।","অন্তর্ভুক্তির অনুভূতি সহযোগিতা বাড়ায়, কিন্তু প্রশ্নহীন আনুগত্য বিচারশক্তি ক্ষয় করে। স্বচ্ছ দাবি, নিরাপদ ভিন্নমত ও জবাবদিহি দেখুন।","উদ্বেগ বাস্তবায়নের প্রকৃত সীমার তথ্য দেয়। কী বদলেছে ও কেন তা দেখিয়ে বোঝান যে আপনি কথা শুনেছেন।"],"correctOption":3,"explanationEn":"Concern is information about a real implementation constraint. Demonstrate that you heard it by showing what changed and why.","explanationBn":"উদ্বেগ বাস্তবায়নের প্রকৃত সীমার তথ্য দেয়। কী বদলেছে ও কেন তা দেখিয়ে বোঝান যে আপনি কথা শুনেছেন।"}]'::jsonb),
  ('disarm-and-infuriate-with-the-mirror-effect', '8adbb5dba9c9a9cd7fc372e6ed7e760c',
    '[{"id":"identify-the-risk","questionEn":"Two teams disagree about who keeps moving their shared deadlines. Which risk does this lesson most directly address?","questionBn":"যৌথ সময়সীমা বারবার কারা সরায় তা নিয়ে দুই দলের মতভেদ আছে। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["An overlong answer can bury the new deadline and the next action.","An overlooked improvement may fail to reach the people who benefit from it.","Feedback collected without clear consent may undermine trust and compromise privacy.","Each team may be reacting to a different account of the same deadline changes."],"optionsBn":["অতিরিক্ত দীর্ঘ উত্তরে নতুন সময়সীমা ও পরের কাজ চাপা পড়তে পারে।","নজর এড়ানো উন্নতি যাঁদের কাজে লাগবে তাঁদের কাছে নাও পৌঁছাতে পারে।","স্পষ্ট সম্মতি ছাড়া মতামত সংগ্রহ করলে আস্থা ও গোপনীয়তা ক্ষতিগ্রস্ত হতে পারে।","একই সময়সীমা পরিবর্তন সম্পর্কে দুই দল ভিন্ন বর্ণনার ভিত্তিতে প্রতিক্রিয়া জানাতে পারে।"],"correctOption":3,"explanationEn":"Each team may be reacting to a different account of the same deadline changes.","explanationBn":"একই সময়সীমা পরিবর্তন সম্পর্কে দুই দল ভিন্ন বর্ণনার ভিত্তিতে প্রতিক্রিয়া জানাতে পারে।"},{"id":"apply-the-boundary","questionEn":"Two teams disagree about who keeps moving their shared deadlines. Which safeguard best prevents misusing this principle here?","questionBn":"যৌথ সময়সীমা বারবার কারা সরায় তা নিয়ে দুই দলের মতভেদ আছে। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Accurate reflection can defuse misunderstanding. Imitation used to ridicule the other party often worsens it.","Collect observations people agreed to share. Limit personal information and keep feedback anonymous when its disclosure could carry a cost.","Basic questions test jargon and hidden assumptions. They are most useful when you can also check the answers against independent evidence.","A fluent presentation reduces friction for the audience. Keep enough of the preparation visible that others can reproduce the result."],"optionsBn":["নির্ভুলভাবে বক্তব্য ফিরিয়ে বললে ভুল বোঝাবুঝি কমে। বিদ্রূপের জন্য অনুকরণ করলে তা প্রায়ই বাড়ে।","মানুষ যে তথ্য ভাগ করতে সম্মত হয়েছে তা সংগ্রহ করুন। ব্যক্তিগত তথ্য সীমিত রাখুন এবং প্রকাশে ক্ষতির আশঙ্কা থাকলে মতামত নামবিহীন রাখুন।","সহজ প্রশ্ন দুর্বোধ্য পরিভাষা ও গোপন অনুমান যাচাই করে। উত্তর স্বাধীন প্রমাণের সঙ্গে মিলিয়ে দেখতে পারলে এগুলো আরও কার্যকর।","সাবলীল উপস্থাপনা দর্শকের বোঝা সহজ করে। অন্যরা যেন ফল পুনরায় তৈরি করতে পারেন, সে জন্য যথেষ্ট প্রস্তুতি দৃশ্যমান রাখুন।"],"correctOption":0,"explanationEn":"Accurate reflection can defuse misunderstanding. Imitation used to ridicule the other party often worsens it.","explanationBn":"নির্ভুলভাবে বক্তব্য ফিরিয়ে বললে ভুল বোঝাবুঝি কমে। বিদ্রূপের জন্য অনুকরণ করলে তা প্রায়ই বাড়ে।"}]'::jsonb),
  ('preach-the-need-for-change', '9159e1ca134be533995a92282faec3ae',
    '[{"id":"identify-the-risk","questionEn":"A new director wants to replace three core tools in one month. Which risk does this lesson most directly address?","questionBn":"নতুন পরিচালক এক মাসের মধ্যে তিনটি প্রধান সরঞ্জাম বদলাতে চান। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Keeping a familiar method after rules change can put the outcome and compliance at risk.","Confrontation at a disadvantage can consume resources without improving your position.","Changing several tools at once makes disruption harder to diagnose and reverse.","Reviewers handling an urgent incident may have too little attention for a major proposal."],"optionsBn":["নিয়ম বদলের পরও পরিচিত পদ্ধতি ধরে রাখলে ফল ও নিয়মপালন দুটিই ঝুঁকিতে পড়তে পারে।","দুর্বল অবস্থায় সরাসরি বিরোধে সম্পদ ক্ষয় হলেও অবস্থার উন্নতি নাও হতে পারে।","একসঙ্গে কয়েকটি সরঞ্জাম বদলালে বিঘ্নের কারণ ধরা ও পূর্বাবস্থায় ফেরা কঠিন হয়।","জরুরি ঘটনা সামলানো পর্যালোচকেরা বড় প্রস্তাবে যথেষ্ট মনোযোগ দিতে নাও পারেন।"],"correctOption":2,"explanationEn":"Changing several tools at once makes disruption harder to diagnose and reverse.","explanationBn":"একসঙ্গে কয়েকটি সরঞ্জাম বদলালে বিঘ্নের কারণ ধরা ও পূর্বাবস্থায় ফেরা কঠিন হয়।"},{"id":"apply-the-boundary","questionEn":"A new director wants to replace three core tools in one month. Which safeguard best prevents misusing this principle here?","questionBn":"নতুন পরিচালক এক মাসের মধ্যে তিনটি প্রধান সরঞ্জাম বদলাতে চান। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Timing involves both opportunity and cost of delay. Set a review date rather than indefinitely waiting for a perfect moment.","Phasing helps people learn what works before a full change. Set clear measures for moving ahead, pausing, or rolling back.","Adapting to ordinary norms can improve cooperation without changing your judgment. Challenge a norm openly if it violates policy or excludes people.","A specific mistake and what you learned make success explainable. Avoid false modesty, especially when another person''s contribution is at stake."],"optionsBn":["সময় বাছাইয়ে সুযোগ ও দেরির ব্যয় দুটোই আছে। আদর্শ মুহূর্তের জন্য অনির্দিষ্ট অপেক্ষা না করে পর্যালোচনার তারিখ ঠিক করুন।","ধাপে কাজ করলে পুরো পরিবর্তনের আগে কী কার্যকর বোঝা যায়। এগোনো, থামা বা পূর্বাবস্থায় ফেরার স্পষ্ট মাপকাঠি দিন।","সাধারণ রীতির সঙ্গে মানিয়ে বিচার অক্ষুণ্ণ রেখেও সহযোগিতা বাড়ানো যায়। নিয়ম ভাঙে বা মানুষকে বাদ দেয় এমন রীতি প্রকাশ্যে প্রশ্ন করুন।","নির্দিষ্ট ভুল ও শেখা বিষয় বললে সাফল্য ব্যাখ্যাযোগ্য হয়। অন্যের অবদান জড়িত থাকলে বিশেষ করে কৃত্রিম বিনয় এড়ান।"],"correctOption":1,"explanationEn":"Phasing helps people learn what works before a full change. Set clear measures for moving ahead, pausing, or rolling back.","explanationBn":"ধাপে কাজ করলে পুরো পরিবর্তনের আগে কী কার্যকর বোঝা যায়। এগোনো, থামা বা পূর্বাবস্থায় ফেরার স্পষ্ট মাপকাঠি দিন।"}]'::jsonb),
  ('never-appear-too-perfect', '3bd082cfb2138ed45e1d480308c7aee1',
    '[{"id":"identify-the-risk","questionEn":"A colleague assumes your successful rollout had no problems. Which risk does this lesson most directly address?","questionBn":"এক সহকর্মী ধরে নিয়েছেন যে সফল বাস্তবায়নে কোনো সমস্যা হয়নি। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["An unsupported public claim can undermine trust in verified work.","An image of effortless success can hide lessons others need to repeat the result.","Unlimited availability can exhaust the mentor and make access less dependable.","An undocumented exception makes accountability and consistent treatment difficult."],"optionsBn":["প্রমাণহীন প্রকাশ্য দাবি যাচাইকৃত কাজের ওপরও আস্থা কমাতে পারে।","অনায়াস সাফল্যের ছবি ফল পুনরায় অর্জনের জন্য দরকারি শিক্ষা আড়াল করতে পারে।","সীমাহীন প্রাপ্যতা পরামর্শদাতাকে ক্লান্ত করে এবং সহায়তা পাওয়া অনিশ্চিত করে।","অলিখিত ব্যতিক্রম জবাবদিহি ও সমান আচরণ কঠিন করে।"],"correctOption":1,"explanationEn":"An image of effortless success can hide lessons others need to repeat the result.","explanationBn":"অনায়াস সাফল্যের ছবি ফল পুনরায় অর্জনের জন্য দরকারি শিক্ষা আড়াল করতে পারে।"},{"id":"apply-the-boundary","questionEn":"A colleague assumes your successful rollout had no problems. Which safeguard best prevents misusing this principle here?","questionBn":"এক সহকর্মী ধরে নিয়েছেন যে সফল বাস্তবায়নে কোনো সমস্যা হয়নি। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["A reliable record includes your own part in a decision. Delegating a task does not transfer responsibility for approving it.","Define the stopping rule before success changes your incentives. A new opportunity needs a fresh decision with its own costs and risks.","A specific mistake and what you learned make success explainable. Avoid false modesty, especially when another person''s contribution is at stake.","Flexibility is about changing methods while honoring durable commitments. Measure alternatives against the same outcome so adaptation remains accountable."],"optionsBn":["নির্ভরযোগ্য নথিতে সিদ্ধান্তে আপনার ভূমিকাও থাকে। কাজ ভাগ করলেই অনুমোদনের দায় অন্যের কাছে যায় না।","সাফল্য আপনার প্রণোদনা বদলানোর আগে থামার নিয়ম ঠিক করুন। নতুন সুযোগের ব্যয় ও ঝুঁকি ধরে নতুন সিদ্ধান্ত নিন।","নির্দিষ্ট ভুল ও শেখা বিষয় বললে সাফল্য ব্যাখ্যাযোগ্য হয়। অন্যের অবদান জড়িত থাকলে বিশেষ করে কৃত্রিম বিনয় এড়ান।","নমনীয়তা হলো দীর্ঘমেয়াদি প্রতিশ্রুতি রেখে পদ্ধতি বদলানো। একই ফলের মাপকাঠি দিয়ে বিকল্প বিচার করলে অভিযোজন জবাবদিহির আওতায় থাকে।"],"correctOption":2,"explanationEn":"A specific mistake and what you learned make success explainable. Avoid false modesty, especially when another person''s contribution is at stake.","explanationBn":"নির্দিষ্ট ভুল ও শেখা বিষয় বললে সাফল্য ব্যাখ্যাযোগ্য হয়। অন্যের অবদান জড়িত থাকলে বিশেষ করে কৃত্রিম বিনয় এড়ান।"}]'::jsonb),
  ('do-not-go-past-the-mark-you-aimed-for', 'b7d7fa32f44181294d914bae37ae11e9',
    '[{"id":"identify-the-risk","questionEn":"A negotiation reaches its agreed goal earlier than expected. Which risk does this lesson most directly address?","questionBn":"আলোচনায় নির্ধারিত লক্ষ্য প্রত্যাশার আগেই অর্জিত হয়েছে। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Additional demands after reaching the goal can reopen a deal that was already settled.","Recurring venting can crowd out coordination without solving the source of distress.","Isolation cuts off early warnings and leaves the team responding late.","Old habits can make colleagues keep treating a new manager as an individual contributor."],"optionsBn":["লক্ষ্য পূরণের পর নতুন দাবি মীমাংসিত চুক্তি আবার আলোচনায় টেনে আনতে পারে।","বারবার অভিযোগে সমন্বয়ের আলোচনা চাপা পড়ে, অথচ কষ্টের উৎস দূর হয় না।","বিচ্ছিন্নতায় আগাম সতর্কতা পৌঁছায় না, ফলে দল দেরিতে সাড়া দেয়।","পুরোনো অভ্যাসে সহকর্মীরা নতুন ব্যবস্থাপককেও স্বতন্ত্র কর্মী হিসেবে দেখতে পারেন।"],"correctOption":0,"explanationEn":"Additional demands after reaching the goal can reopen a deal that was already settled.","explanationBn":"লক্ষ্য পূরণের পর নতুন দাবি মীমাংসিত চুক্তি আবার আলোচনায় টেনে আনতে পারে।"},{"id":"apply-the-boundary","questionEn":"A negotiation reaches its agreed goal earlier than expected. Which safeguard best prevents misusing this principle here?","questionBn":"আলোচনায় নির্ধারিত লক্ষ্য প্রত্যাশার আগেই অর্জিত হয়েছে। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["A new role becomes credible through repeated behavior. Communicate which responsibilities changed and who now owns your former work.","Calm authority comes from owning a decision process. Make space for relevant objections, especially from people with lower status.","Stop investing attention after the answer is settled, but keep lessons that improve the next attempt. Persistent problems still need a responsible escalation path.","Define the stopping rule before success changes your incentives. A new opportunity needs a fresh decision with its own costs and risks."],"optionsBn":["পুনরাবৃত্ত আচরণে নতুন ভূমিকা বিশ্বাসযোগ্য হয়। কোন দায়িত্ব বদলেছে এবং আগের কাজ এখন কার তা জানান।","শান্ত কর্তৃত্ব আসে সিদ্ধান্তের প্রক্রিয়ার দায় নেওয়া থেকে। প্রাসঙ্গিক আপত্তির সুযোগ রাখুন, বিশেষ করে কম ক্ষমতাসম্পন্ন মানুষের জন্য।","সিদ্ধান্ত চূড়ান্ত হলে সময় ব্যয় থামান, তবে পরের চেষ্টা উন্নত করে এমন শিক্ষা রাখুন। চলমান সমস্যার জন্য দায়িত্বপূর্ণভাবে বিষয় তোলার পথ দরকার।","সাফল্য আপনার প্রণোদনা বদলানোর আগে থামার নিয়ম ঠিক করুন। নতুন সুযোগের ব্যয় ও ঝুঁকি ধরে নতুন সিদ্ধান্ত নিন।"],"correctOption":3,"explanationEn":"Define the stopping rule before success changes your incentives. A new opportunity needs a fresh decision with its own costs and risks.","explanationBn":"সাফল্য আপনার প্রণোদনা বদলানোর আগে থামার নিয়ম ঠিক করুন। নতুন সুযোগের ব্যয় ও ঝুঁকি ধরে নতুন সিদ্ধান্ত নিন।"}]'::jsonb),
  ('assume-formlessness', '057fd566bc4ccd292cc7d04ae0218ba5',
    '[{"id":"identify-the-risk","questionEn":"A regulatory change invalidates the team''s usual delivery process. Which risk does this lesson most directly address?","questionBn":"নিয়ম বদলে দলের প্রচলিত সরবরাহ পদ্ধতি আর কার্যকর নেই। এই পাঠটি সবচেয়ে সরাসরি কোন ঝুঁকির কথা বলে?","optionsEn":["Confrontation at a disadvantage can consume resources without improving your position.","Reviewers handling an urgent incident may have too little attention for a major proposal.","Ignoring unfamiliar communication norms may create friction before substantive issues get a hearing.","Keeping a familiar method after rules change can put the outcome and compliance at risk."],"optionsBn":["দুর্বল অবস্থায় সরাসরি বিরোধে সম্পদ ক্ষয় হলেও অবস্থার উন্নতি নাও হতে পারে।","জরুরি ঘটনা সামলানো পর্যালোচকেরা বড় প্রস্তাবে যথেষ্ট মনোযোগ দিতে নাও পারেন।","অপরিচিত যোগাযোগরীতি উপেক্ষা করলে মূল বিষয় শোনার আগেই বিরোধ তৈরি হতে পারে।","নিয়ম বদলের পরও পরিচিত পদ্ধতি ধরে রাখলে ফল ও নিয়মপালন দুটিই ঝুঁকিতে পড়তে পারে।"],"correctOption":3,"explanationEn":"Keeping a familiar method after rules change can put the outcome and compliance at risk.","explanationBn":"নিয়ম বদলের পরও পরিচিত পদ্ধতি ধরে রাখলে ফল ও নিয়মপালন দুটিই ঝুঁকিতে পড়তে পারে।"},{"id":"apply-the-boundary","questionEn":"A regulatory change invalidates the team''s usual delivery process. Which safeguard best prevents misusing this principle here?","questionBn":"নিয়ম বদলে দলের প্রচলিত সরবরাহ পদ্ধতি আর কার্যকর নেই। এখানে নীতিটির অপব্যবহার ঠেকাতে কোন সতর্কতা সবচেয়ে কার্যকর?","optionsEn":["Flexibility is about changing methods while honoring durable commitments. Measure alternatives against the same outcome so adaptation remains accountable.","Adapting to ordinary norms can improve cooperation without changing your judgment. Challenge a norm openly if it violates policy or excludes people.","Phasing helps people learn what works before a full change. Set clear measures for moving ahead, pausing, or rolling back.","If quality or safety is at risk, raise the facts through the responsible channel promptly. Giving credit should never obscure who did the work."],"optionsBn":["নমনীয়তা হলো দীর্ঘমেয়াদি প্রতিশ্রুতি রেখে পদ্ধতি বদলানো। একই ফলের মাপকাঠি দিয়ে বিকল্প বিচার করলে অভিযোজন জবাবদিহির আওতায় থাকে।","সাধারণ রীতির সঙ্গে মানিয়ে বিচার অক্ষুণ্ণ রেখেও সহযোগিতা বাড়ানো যায়। নিয়ম ভাঙে বা মানুষকে বাদ দেয় এমন রীতি প্রকাশ্যে প্রশ্ন করুন।","ধাপে কাজ করলে পুরো পরিবর্তনের আগে কী কার্যকর বোঝা যায়। এগোনো, থামা বা পূর্বাবস্থায় ফেরার স্পষ্ট মাপকাঠি দিন।","মান বা নিরাপত্তা ঝুঁকিতে থাকলে দায়িত্বপ্রাপ্ত পথে দ্রুত তথ্য জানান। কৃতিত্ব ভাগ করতে গিয়ে কে কাজ করেছেন তা আড়াল করা উচিত নয়।"],"correctOption":0,"explanationEn":"Flexibility is about changing methods while honoring durable commitments. Measure alternatives against the same outcome so adaptation remains accountable.","explanationBn":"নমনীয়তা হলো দীর্ঘমেয়াদি প্রতিশ্রুতি রেখে পদ্ধতি বদলানো। একই ফলের মাপকাঠি দিয়ে বিকল্প বিচার করলে অভিযোজন জবাবদিহির আওতায় থাকে।"}]'::jsonb)
)
update public.content_laws as law
set assessment = law.assessment || jsonb_build_object(
  'passPercentage', 67,
  'questions', (law.assessment->'questions') || seed.questions
)
from quiz_seed as seed
where law.slug = seed.slug
